//! End-to-end `note.*` service tests over a temp `SQLite` store. Pure content
//! math is covered in `note_ops`; these assert persistence, the setContent
//! reduction guard, spec-title skip, workspace scoping, and error mapping.

use std::path::PathBuf;
use std::sync::Mutex;

use intent_core::{
    now_iso, AgentId, AgentSession, AgentStatus, ContentType, Error, Note, NoteAddInput,
    NoteCreate, NoteEditInput, NoteEditLinesInput, NoteId, NoteMetadata, NoteUpdateInput,
    NoteVisibility, Workspace, WorkspaceActivity, WorkspaceApi, WorkspaceAttention, WorkspaceId,
    WorkspaceStatus,
};
use intent_store::Store;

use crate::Services;

/// Runs before `main()` — and therefore before any test threads exist, making
/// `set_var` race-free. Node children spawned by lib tests (e.g. the real
/// `auggie` CLI in `auto_commit` tests) inherit this and skip
/// `module.enableCompileCache()`, which would otherwise leave a
/// `node-compile-cache/` residue at the TMPDIR root after the suite.
#[ctor::ctor(unsafe)]
fn disable_node_compile_cache() {
    std::env::set_var("NODE_DISABLE_COMPILE_CACHE", "1");
}

/// Guard for tests that mutate debounce env vars to prevent parallel test
/// races (`env::set_var` is process-global). Supports both `LAST_ACTIVITY` and
/// `WORKSPACE_IDLE` debounce vars.
static ENV_DEBOUNCE_LOCK: Mutex<()> = Mutex::new(());

/// RAII guard for debounce env vars: holds the lock, sets the vars, and restores
/// on drop to prevent leakage into other tests.
pub(crate) struct DebounceEnvGuard {
    _lock: std::sync::MutexGuard<'static, ()>,
    prior_last_activity: Option<std::ffi::OsString>,
    prior_workspace_idle: Option<std::ffi::OsString>,
}

impl DebounceEnvGuard {
    pub(crate) fn new(millis: &str) -> Self {
        let lock = ENV_DEBOUNCE_LOCK.lock().unwrap();
        let prior_last_activity = std::env::var_os("LAST_ACTIVITY_DEBOUNCE_TEST_MS");
        let prior_workspace_idle = std::env::var_os("WORKSPACE_IDLE_DEBOUNCE_TEST_MS");
        std::env::set_var("LAST_ACTIVITY_DEBOUNCE_TEST_MS", millis);
        std::env::set_var("WORKSPACE_IDLE_DEBOUNCE_TEST_MS", millis);
        Self {
            _lock: lock,
            prior_last_activity,
            prior_workspace_idle,
        }
    }
}

impl Drop for DebounceEnvGuard {
    fn drop(&mut self) {
        if let Some(val) = &self.prior_last_activity {
            std::env::set_var("LAST_ACTIVITY_DEBOUNCE_TEST_MS", val);
        } else {
            std::env::remove_var("LAST_ACTIVITY_DEBOUNCE_TEST_MS");
        }
        if let Some(val) = &self.prior_workspace_idle {
            std::env::set_var("WORKSPACE_IDLE_DEBOUNCE_TEST_MS", val);
        } else {
            std::env::remove_var("WORKSPACE_IDLE_DEBOUNCE_TEST_MS");
        }
    }
}

/// Create a temp dir with a recognizable `prefix` under the system temp root.
/// The returned guard removes the dir on drop (including on panic); set
/// `INTENTD_TEST_KEEP_TMP` (non-empty) to keep it around for debugging.
pub(crate) fn test_tempdir(prefix: &str) -> tempfile::TempDir {
    let mut dir = tempfile::Builder::new()
        .prefix(prefix)
        .tempdir()
        .expect("create test tempdir");
    if std::env::var_os("INTENTD_TEST_KEEP_TMP").is_some_and(|v| !v.is_empty()) {
        dir.disable_cleanup(true);
    }
    dir
}

pub(crate) struct TempDb {
    pub(crate) path: PathBuf,
}

impl TempDb {
    pub(crate) fn new() -> Self {
        let path = std::env::temp_dir().join(format!("intentd-svc-{}.db", uuid::Uuid::new_v4()));
        Self { path }
    }
}

impl Drop for TempDb {
    fn drop(&mut self) {
        for suffix in ["", "-wal", "-shm", ".config.toml"] {
            let _ = std::fs::remove_file(PathBuf::from(format!("{}{suffix}", self.path.display())));
        }
    }
}

/// A settings registry (backed by a config file next to the temp db, removed
/// by [`TempDb`]'s drop) seeding `providers.active = "auggie"`: since
/// monorepo#3044 there is no positional provider fallback, so tests that
/// create/delegate agents without an explicit provider or model need a
/// configured default to resolve to. The `providers.paths` override points
/// auggie at a deterministic executable so availability checks
/// (`agent.delegate`) pass without the real binary on the test host
/// (monorepo#3162).
pub(crate) fn test_registry_with_default_provider(
    tmp: &TempDb,
) -> std::sync::Arc<crate::SettingsRegistry> {
    let cfg = PathBuf::from(format!("{}.config.toml", tmp.path.display()));
    let registry = std::sync::Arc::new(crate::SettingsRegistry::load(cfg).expect("load registry"));
    registry
        .apply(&[
            ("providers.active".to_string(), serde_json::json!("auggie")),
            (
                "providers.paths".to_string(),
                serde_json::json!({ "auggie": "/bin/sh" }),
            ),
        ])
        .expect("seed default provider");
    registry
}

/// Drop-cleanup wrapper around a per-test workspaces root, paired with the
/// intent-services hermetic-tests guard (see `default_workspaces_root`). Every
/// test that constructs a `Services` reachable from workspace provisioning
/// **must** attach one via `.with_workspaces_root(root.path().to_path_buf())`;
/// otherwise the guard panics rather than writing under `~/intent/workspaces`.
pub(crate) struct WorkspacesRoot(PathBuf);

impl WorkspacesRoot {
    pub(crate) fn new() -> Self {
        let p = std::env::temp_dir().join(format!("intentd-wss-{}", uuid::Uuid::new_v4()));
        std::fs::create_dir_all(&p).expect("mkdir hermetic workspaces root");
        Self(p)
    }

    pub(crate) fn path(&self) -> &std::path::Path {
        &self.0
    }
}

impl Drop for WorkspacesRoot {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

pub(crate) fn workspace(id: &WorkspaceId) -> Workspace {
    let ts = now_iso();
    Workspace {
        id: id.clone(),
        title: "WS".to_string(),
        branch: "main".to_string(),
        base_ref: None,
        base_commit_sha: None,
        status: WorkspaceStatus::Active,
        status_message: None,
        status_image_asset_id: None,
        activity: WorkspaceActivity::Idle,
        attention: WorkspaceAttention::None,
        created_at: ts.clone(),
        updated_at: ts,
        last_activity: None,
        tags: vec![],
        path: None,
        repository_path: None,
        repository_owner: None,
        repository_name: None,
        worktree_path: None,
        scope: None,
        skip_worktree: false,
        setup_script: None,
        is_remote: false,
        default_model: None,
        pr_number: None,
        pr_url: None,
        pr_status: None,
        active_pull_request: None,
        pull_requests: None,
        context_links: None,
        archived: false,
        archived_at: None,
        task_stats: None,
        agent_summary: None,
        diff_summary: None,
        token_usage: None,
        cow_supported: None,
        display_status: None,
        waiting: false,
        checkout_mode: None,
        disk_usage: None,
        pending_delete_at: None,
    }
}

fn note(ws: &WorkspaceId, id: &str, content: &str) -> Note {
    let ts = now_iso();
    Note {
        id: NoteId::from(id),
        workspace_id: ws.clone(),
        title: "Title".to_string(),
        content: content.to_string(),
        content_type: ContentType::Markdown,
        tags: vec![],
        is_pinned: false,
        is_archived: false,
        is_default: false,
        parent_id: None,
        visibility: NoteVisibility::Workspace,
        metadata: NoteMetadata::default(),
        created_at: ts.clone(),
        rev: 0,
        updated_at: ts,
    }
}

async fn setup(content: &str) -> (TempDb, Services, WorkspaceId, NoteId) {
    let tmp = TempDb::new();
    let store = Store::open(&tmp.path).await.expect("open store");
    let ws = WorkspaceId::new();
    store.insert_workspace(&workspace(&ws)).await.expect("ws");
    let id = NoteId::from("n1");
    store
        .insert_note(&note(&ws, "n1", content))
        .await
        .expect("note");
    let services = Services::new(store);
    (tmp, services, ws, id)
}

/// `workspace.list` / `workspace.get` populate the iOS card aggregates
/// (`taskStats` / `agentSummary` / `diffSummary`) computed from the workspace's
/// real notes, agents, and git state, with the nested wire shape iOS decodes.
#[tokio::test]
async fn workspace_list_and_get_populate_card_aggregates() {
    use intent_core::{AgentId, AgentSession, AgentStatus, TaskMetadata, TaskStatus};

    let tmp = TempDb::new();
    let store = Store::open(&tmp.path).await.expect("open store");
    let ws = WorkspaceId::new();
    store.insert_workspace(&workspace(&ws)).await.expect("ws");

    // Spec note links five task notes (the cancelled one is excluded from
    // `total`; the blocked one counts in `total` but NOT `inProgress`); a
    // spec-linked filter is exercised since the spec body has links.
    let spec = note(
        &ws,
        "spec",
        "- [A](intent://local/task/task-a)\n- [B](intent://local/task/task-b)\n\
         - [C](intent://local/task/task-c)\n- [D](intent://local/task/task-d)\n\
         - [E](intent://local/task/task-e)",
    );
    store.insert_note(&spec).await.expect("spec");

    let mk_task = |id: &str, status: TaskStatus| {
        let mut tn = note(&ws, id, "body");
        tn.parent_id = Some(NoteId::from("spec"));
        tn.metadata.task = Some(TaskMetadata {
            status,
            ..Default::default()
        });
        tn
    };
    store
        .insert_note(&mk_task("task-a", TaskStatus::Complete))
        .await
        .unwrap();
    store
        .insert_note(&mk_task("task-b", TaskStatus::InProgress))
        .await
        .unwrap();
    store
        .insert_note(&mk_task("task-c", TaskStatus::ReviewRequired))
        .await
        .unwrap();
    store
        .insert_note(&mk_task("task-d", TaskStatus::Cancelled))
        .await
        .unwrap();
    store
        .insert_note(&mk_task("task-e", TaskStatus::Blocked))
        .await
        .unwrap();

    // Distinct `created_at` values pin the `ORDER BY created_at` agent
    // ordering: seeding both agents with `now_iso()` lets the timestamps tie
    // under parallel-test load, flipping `agents[0]` (monorepo#967).
    let mk_agent =
        |id: &str, name: &str, specialist: Option<&str>, created_at: &str| AgentSession {
            harness_version: intent_core::CURRENT_HARNESS_VERSION.to_string(),
            harness_features: None,
            id: AgentId::from(id),
            workspace_id: ws.clone(),
            parent_agent_id: None,
            backend_session_id: None,
            acp_session_id: None,
            name: name.to_string(),
            name_explicitly_set: true,
            model: None,
            reasoning_effort: None,
            effort_levels: None,
            provider: None,
            system_prompt: None,
            specialist: specialist.map(str::to_string),
            status: AgentStatus::Active,
            is_active: true,
            messages: vec![],
            stats: None,
            task_note_id: None,
            skip_auto_commit: false,
            completion_report: None,
            completion_report_timestamp: None,
            attention_request_kind: None,
            attention_request_reason: None,
            attention_request_timestamp: None,
            delegation_depth: None,
            initial_message: None,
            context_references: None,
            image_blocks: None,
            file_blocks: None,
            is_background: false,
            metadata: None,
            created_at: created_at.to_string(),
            updated_at: now_iso(),
            sandbox_id: None,
            sandbox_path: None,
            sandbox_branch: None,
            stop_reason: None,
            stop_reason_timestamp: None,
            session_corrupted: false,
            pending_delete_at: None,
            retired_at: None,
        };
    store
        .insert_agent_session(&mk_agent(
            "agent-1",
            "Builder",
            Some("implementor"),
            "2026-01-01T00:00:01Z",
        ))
        .await
        .unwrap();
    // agent-2 is delegated by agent-1: `agentSummary` surfaces the session's
    // delegation parent as `parentAgentId` (v2.9, additive).
    let mut delegated = mk_agent("agent-2", "Verifier", None, "2026-01-01T00:00:02Z");
    delegated.parent_agent_id = Some(AgentId::from("agent-1"));
    store.insert_agent_session(&delegated).await.unwrap();

    // Hermetic root: the get/list enrichment probes the workspaces root for
    // `cowSupported`, and tests must never touch `~/intent/workspaces`.
    let root = tempfile::tempdir().expect("temp workspaces root");
    let svc = Services::new(store).with_workspaces_root(root.path().to_path_buf());

    // workspace.get
    let got = svc.get_workspace(ws.clone()).await.expect("get");
    let stats = got.task_stats.expect("task_stats present");
    assert_eq!(stats.total, 4); // cancelled excluded; blocked counts in total
    assert_eq!(stats.completed, 1);
    assert_eq!(stats.in_progress, 2); // in_progress + review_required; blocked excluded
    let summary = got.agent_summary.expect("agent_summary present");
    assert_eq!(summary.count, 2);
    assert!(summary.agents.iter().any(|a| a.name == "Builder"
        && a.specialist.as_deref() == Some("implementor")
        && !a.is_streaming
        && !a.is_responding
        && a.parent_agent_id.is_none()));
    // The delegated agent carries its parent's id (root agents omit it).
    assert!(summary.agents.iter().any(|a| a.name == "Verifier"
        && a.parent_agent_id.as_ref().map(AgentId::as_str) == Some("agent-1")));
    // `agentIds` mirrors the agents used to build `agents` (forward-compat).
    let summary_ids: Vec<_> = summary.agent_ids.iter().map(|i| i.0.clone()).collect();
    let agent_ids: Vec<_> = summary.agents.iter().map(|a| a.id.0.clone()).collect();
    assert_eq!(summary_ids, agent_ids);
    assert!(summary_ids.contains(&"agent-1".to_string()));
    // No git worktree → diffSummary omitted.
    assert!(got.diff_summary.is_none());

    // workspace.list carries the same aggregates; assert the nested wire shape.
    let list = svc.list_workspaces(false).await.expect("list");
    let v = serde_json::to_value(&list[0]).unwrap();
    assert_eq!(v["taskStats"]["total"], 4);
    assert_eq!(v["taskStats"]["completed"], 1);
    assert_eq!(v["taskStats"]["inProgress"], 2);
    assert_eq!(v["agentSummary"]["count"], 2);
    assert_eq!(v["agentSummary"]["agents"][0]["id"], "agent-1");
    // `parentAgentId` wire shape: omitted (not null) on roots, camelCased when set.
    assert!(v["agentSummary"]["agents"][0]
        .get("parentAgentId")
        .is_none());
    assert_eq!(v["agentSummary"]["agents"][1]["parentAgentId"], "agent-1");
    assert_eq!(v["agentSummary"]["agentIds"][0], "agent-1");
    assert_eq!(v["agentSummary"]["agentIds"].as_array().unwrap().len(), 2);
    assert!(v.get("diffSummary").is_none());
    // diskUsage left the hot read path (monorepo#1396): list/get rows never
    // carry it — clients fetch it via the on-demand `workspace.diskUsage`.
    assert!(got.disk_usage.is_none());
    assert!(v.get("diskUsage").is_none());
}

/// List-frame slimming (monorepo#3041): `workspace.list` rows never carry
/// `tokenUsage` (detail-only — clients read it via `workspace.getTokenUsage`
/// and the tokenUsage-changed event), and ARCHIVED rows additionally omit
/// `agentSummary` (no HUD/coverflow agent card renders for an archived
/// workspace). Active rows keep the full `agentSummary`, and `workspace.get`
/// keeps serving both fields for detail reads.
#[tokio::test]
async fn workspace_list_slims_token_usage_and_archived_agent_summary() {
    use std::collections::BTreeMap;

    use intent_core::{AgentId, AgentSession, AgentStatus, TokenUsage, TokenUsageTotals};

    let tmp = TempDb::new();
    let store = Store::open(&tmp.path).await.expect("open store");

    let usage = TokenUsage {
        by_agent_id: BTreeMap::from([(
            "agent-1".to_string(),
            TokenUsageTotals {
                input_tokens: 10,
                output_tokens: 20,
                cache_read_tokens: 5,
                cache_creation_tokens: 3,
                thought_tokens: 0,
                cost: None,
            },
        )]),
        totals: TokenUsageTotals {
            input_tokens: 10,
            output_tokens: 20,
            cache_read_tokens: 5,
            cache_creation_tokens: 3,
            thought_tokens: 0,
            cost: None,
        },
        by_model: BTreeMap::new(),
        last_scan_at: Some(now_iso()),
    };

    let ws_active = WorkspaceId::new();
    let mut active = workspace(&ws_active);
    active.token_usage = Some(usage.clone());
    store.insert_workspace(&active).await.expect("active ws");

    let ws_archived = WorkspaceId::new();
    let mut archived = workspace(&ws_archived);
    archived.archived = true;
    archived.archived_at = Some(now_iso());
    archived.token_usage = Some(usage);
    store
        .insert_workspace(&archived)
        .await
        .expect("archived ws");

    // One live session per workspace so the enrichment builds an
    // `agentSummary` for both rows before the archived one is slimmed.
    let mk_session = |id: &str, ws: &WorkspaceId| AgentSession {
        harness_version: intent_core::CURRENT_HARNESS_VERSION.to_string(),
        harness_features: None,
        id: AgentId::from(id),
        workspace_id: ws.clone(),
        parent_agent_id: None,
        backend_session_id: None,
        acp_session_id: None,
        name: "Agent".to_string(),
        name_explicitly_set: true,
        model: None,
        reasoning_effort: None,
        effort_levels: None,
        provider: None,
        system_prompt: None,
        specialist: None,
        status: AgentStatus::Idle,
        is_active: false,
        messages: vec![],
        stats: None,
        task_note_id: None,
        skip_auto_commit: false,
        completion_report: None,
        completion_report_timestamp: None,
        attention_request_kind: None,
        attention_request_reason: None,
        attention_request_timestamp: None,
        delegation_depth: None,
        initial_message: None,
        context_references: None,
        image_blocks: None,
        file_blocks: None,
        is_background: false,
        metadata: None,
        created_at: now_iso(),
        updated_at: now_iso(),
        sandbox_id: None,
        sandbox_path: None,
        sandbox_branch: None,
        stop_reason: None,
        stop_reason_timestamp: None,
        session_corrupted: false,
        pending_delete_at: None,
        retired_at: None,
    };
    store
        .insert_agent_session(&mk_session("agent-1", &ws_active))
        .await
        .expect("active session");
    store
        .insert_agent_session(&mk_session("agent-2", &ws_archived))
        .await
        .expect("archived session");

    let root = tempfile::tempdir().expect("temp workspaces root");
    let svc = Services::new(store).with_workspaces_root(root.path().to_path_buf());

    // Full list: tokenUsage never present; agentSummary only on active rows.
    let list = svc.list_workspaces(true).await.expect("list");
    let row_active = list.iter().find(|w| w.id == ws_active).expect("active row");
    let row_archived = list
        .iter()
        .find(|w| w.id == ws_archived)
        .expect("archived row");
    assert!(row_active.token_usage.is_none(), "list: tokenUsage omitted");
    assert!(
        row_archived.token_usage.is_none(),
        "list: tokenUsage omitted on archived rows"
    );
    let summary = row_active
        .agent_summary
        .as_ref()
        .expect("active row keeps agentSummary");
    assert_eq!(summary.count, 1);
    assert!(
        row_archived.agent_summary.is_none(),
        "archived row omits agentSummary"
    );
    // Wire shape: absent, never null (skip_serializing_if on both fields).
    let v = serde_json::to_value(row_archived).unwrap();
    assert!(v.get("tokenUsage").is_none());
    assert!(v.get("agentSummary").is_none());

    // Lite list (workspace.subscribe seq-0): tokenUsage stripped the same way.
    let lite = svc.list_workspaces_lite(true).await.expect("lite list");
    assert!(lite.iter().all(|w| w.token_usage.is_none()));

    // workspace.get keeps both fields for detail reads — archived included.
    let got_active = svc.get_workspace(ws_active).await.expect("get active");
    assert!(got_active.token_usage.is_some(), "get keeps tokenUsage");
    assert!(got_active.agent_summary.is_some());
    let got_archived = svc.get_workspace(ws_archived).await.expect("get archived");
    assert!(got_archived.token_usage.is_some());
    assert!(
        got_archived.agent_summary.is_some(),
        "get keeps agentSummary on archived workspaces"
    );
}

/// Frame-size regression guard for monorepo#3041: ~130 realistic rows —
/// dogfooding-shaped (mostly archived, each with agent sessions, a fat
/// persisted tokenUsage rollup, PR linkage, and a status message) — must
/// serialize under the 1 MiB transport warn threshold once the list paths
/// slim `tokenUsage` (all rows) and `agentSummary` (archived rows).
#[tokio::test]
async fn workspace_list_of_130_realistic_rows_stays_under_1mib() {
    // Dogfooding shape (issue math: ~10 KB/row at 130 workspaces): the vast
    // majority archived, each with the agent sessions a coordinator +
    // sub-agent workflow accumulates over a workspace's life. Unslimmed this
    // dataset serializes well over 1 MiB — the assertion below only holds
    // with the list-path slimming in place.
    const WORKSPACES: usize = 130;
    const ACTIVE: usize = 8;
    const SESSIONS_PER_WS: u64 = 20;
    use std::collections::BTreeMap;

    use intent_core::{
        AgentId, AgentSession, AgentStatus, PullRequestInfo, PullRequestStatus, TokenUsage,
        TokenUsageTotals,
    };

    let tmp = TempDb::new();
    let store = Store::open(&tmp.path).await.expect("open store");

    let totals = |n: u64| TokenUsageTotals {
        input_tokens: 1_000_000 + n,
        output_tokens: 500_000 + n,
        cache_read_tokens: 2_000_000 + n,
        cache_creation_tokens: 300_000 + n,
        thought_tokens: 0,
        cost: None,
    };
    let mk_session = |id: String, ws: &WorkspaceId, n: u64| AgentSession {
        harness_version: intent_core::CURRENT_HARNESS_VERSION.to_string(),
        harness_features: None,
        id: AgentId::from(id.as_str()),
        workspace_id: ws.clone(),
        parent_agent_id: (n > 0).then(|| AgentId::from(format!("{}-0", ws.as_str()).as_str())),
        backend_session_id: None,
        acp_session_id: None,
        name: format!("Fix workspace panel focus regression {n}"),
        name_explicitly_set: true,
        model: None,
        reasoning_effort: None,
        effort_levels: None,
        provider: None,
        system_prompt: None,
        specialist: Some("implementor".to_string()),
        status: AgentStatus::Idle,
        is_active: false,
        messages: vec![],
        stats: None,
        task_note_id: None,
        skip_auto_commit: false,
        completion_report: None,
        completion_report_timestamp: None,
        attention_request_kind: None,
        attention_request_reason: None,
        attention_request_timestamp: None,
        delegation_depth: None,
        initial_message: None,
        context_references: None,
        image_blocks: None,
        file_blocks: None,
        is_background: false,
        metadata: None,
        created_at: now_iso(),
        updated_at: now_iso(),
        sandbox_id: None,
        sandbox_path: None,
        sandbox_branch: None,
        stop_reason: None,
        stop_reason_timestamp: None,
        session_corrupted: false,
        pending_delete_at: None,
        retired_at: None,
    };

    for i in 0..WORKSPACES {
        let ws = WorkspaceId::new();
        let mut row = workspace(&ws);
        row.title = format!("Fix issue #{i}: bring the panel focus back after modal close");
        row.status_message = Some(
            "PR #123 open and waiting for review. All gates green; reviewer comments \
             addressed and threads resolved."
                .to_string(),
        );
        row.repository_path = Some("/home/user/src/intent/monorepo/packages/intentd".to_string());
        row.worktree_path = Some(format!("/home/user/intent/workspaces/ws-{i}/monorepo"));
        row.base_commit_sha = Some("f759124bdeadbeefdeadbeefdeadbeefdeadbeef".to_string());
        row.pull_requests = Some(vec![PullRequestInfo {
            id: format!("pr-{i}"),
            number: 1000 + i as u64,
            url: format!("https://github.com/intent-hq/intentd/pull/{}", 1000 + i),
            title: format!("fix: bring panel focus back after modal close (#{i})"),
            status: PullRequestStatus::Merged,
            created_at: now_iso(),
            updated_at: now_iso(),
            base_ref: Some("main".to_string()),
            head_ref: Some(format!("fix/{i}-panel-focus")),
            head_sha: Some("a1b2c3d4e5f6a1b2c3d4e5f6a1b2c3d4e5f6a1b2".to_string()),
            author: Some("dev".to_string()),
            mergeable: None,
            mergeable_state: None,
            is_draft: Some(false),
        }]);
        // Fat persisted rollup: 8 agents + 3 models per workspace (the field
        // list rows must no longer carry).
        row.token_usage = Some(TokenUsage {
            by_agent_id: (0..SESSIONS_PER_WS)
                .map(|n| (format!("agent-{}-{n}", uuid::Uuid::new_v4()), totals(n)))
                .collect(),
            totals: totals(9),
            by_model: BTreeMap::from([
                ("claude-sonnet-4-5".to_string(), totals(1)),
                ("claude-opus-4-1".to_string(), totals(2)),
                ("gpt-5".to_string(), totals(3)),
            ]),
            last_scan_at: Some(now_iso()),
        });
        if i >= ACTIVE {
            row.archived = true;
            row.archived_at = Some(now_iso());
        }
        store.insert_workspace(&row).await.expect("ws");
        for n in 0..SESSIONS_PER_WS {
            store
                .insert_agent_session(&mk_session(format!("{}-{n}", ws.as_str()), &ws, n))
                .await
                .expect("session");
        }
    }

    let root = tempfile::tempdir().expect("temp workspaces root");
    let svc = Services::new(store).with_workspaces_root(root.path().to_path_buf());

    let list = svc.list_workspaces(true).await.expect("list");
    assert_eq!(list.len(), WORKSPACES);
    let payload = serde_json::to_string(&serde_json::json!({ "workspaces": list })).unwrap();
    assert!(
        payload.len() < 1024 * 1024,
        "workspace.list for {WORKSPACES} realistic rows must stay under the 1 MiB \
         frame warn threshold, got {} bytes",
        payload.len()
    );
}

/// `workspace.diskUsage` cache-state → response mapping: a qualifying row
/// with a provisioned directory answers `{ refreshing: true }` first (walk
/// armed, field omitted), backfills to `{ diskUsage, refreshing: false }`
/// once the walk settles, a skip-isolation row and a never-provisioned
/// directory answer `{ refreshing: false }` without arming anything, and an
/// unknown id is `NotFound`.
#[tokio::test]
async fn workspace_disk_usage_op_maps_cache_states() {
    let tmp = TempDb::new();
    let store = Store::open(&tmp.path).await.expect("open store");
    let root = WorkspacesRoot::new();

    // Qualifying row with a provisioned daemon-managed directory.
    let ws = WorkspaceId::new();
    let mut managed = workspace(&ws);
    let checkout = root.path().join(ws.as_str()).join("repo");
    std::fs::create_dir_all(&checkout).expect("mkdir checkout");
    std::fs::write(checkout.join("data.bin"), vec![0xCD; 8192]).expect("seed file");
    managed.worktree_path = Some(checkout.to_string_lossy().into_owned());
    store.insert_workspace(&managed).await.expect("ws");

    // Skip-isolation row: no daemon-managed directory by construction.
    let ws_skip = WorkspaceId::new();
    let mut skip = workspace(&ws_skip);
    skip.skip_worktree = true;
    store.insert_workspace(&skip).await.expect("ws skip");

    // Qualifying row whose directory was never provisioned on disk.
    let ws_bare = WorkspaceId::new();
    store
        .insert_workspace(&workspace(&ws_bare))
        .await
        .expect("ws bare");

    let svc = Services::new(store).with_workspaces_root(root.path().to_path_buf());

    // First call arms the walk: refreshing true, field omitted (absent, not null).
    let first = svc.workspace_disk_usage_op(ws.clone()).await.expect("op");
    assert_eq!(first["refreshing"], serde_json::json!(true));
    assert!(first.get("diskUsage").is_none(), "{first}");

    // Bounded poll until the backfill settles: diskUsage + refreshing false.
    let mut settled = None;
    for _ in 0..200 {
        let got = svc.workspace_disk_usage_op(ws.clone()).await.expect("op");
        if got.get("diskUsage").is_some() && got["refreshing"] == serde_json::json!(false) {
            settled = Some(got);
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(10)).await;
    }
    let got = settled.expect("diskUsage backfilled + settled");
    assert!(got["diskUsage"]["bytes"].as_u64().unwrap() >= 8192);
    assert_eq!(got["diskUsage"]["fileCount"], serde_json::json!(1));

    // Skip-isolation and never-provisioned rows: nothing to walk or refresh.
    for id in [&ws_skip, &ws_bare] {
        let got = svc.workspace_disk_usage_op(id.clone()).await.expect("op");
        assert_eq!(got["refreshing"], serde_json::json!(false), "{got}");
        assert!(got.get("diskUsage").is_none(), "{got}");
    }

    // Unknown id: standard NotFound.
    let err = svc
        .workspace_disk_usage_op(WorkspaceId::from("ws_missing"))
        .await
        .expect_err("unknown id errors");
    assert!(matches!(err, crate::Error::NotFound(_)), "{err:?}");
}

/// Parity: the cheap store-level `count_task_stats` query (no note-body
/// hydration) must match the enriched `compute_task_stats` over hydrated
/// notes for the same seeded data, across the spec-linked filter, the
/// no-links backward-compat fallback, and the missing-spec case.
#[tokio::test]
async fn cheap_task_stats_matches_enriched_compute_task_stats() {
    use intent_core::{TaskMetadata, TaskStatus};

    let tmp = TempDb::new();
    let store = Store::open(&tmp.path).await.expect("open store");

    let mk_task = |ws: &WorkspaceId, id: &str, parent: Option<&str>, status: TaskStatus| {
        let mut tn = note(ws, id, "body");
        tn.parent_id = parent.map(NoteId::from);
        tn.metadata.task = Some(TaskMetadata {
            status,
            ..Default::default()
        });
        tn
    };

    // Case 1: spec with links — one status per bucket, plus rows the filter
    // must exclude (unlinked child, non-spec parent, no parent, non-task
    // child, and a linked id with no matching note).
    let ws1 = WorkspaceId::new();
    store.insert_workspace(&workspace(&ws1)).await.expect("ws1");
    let spec = note(
        &ws1,
        "spec",
        "- [A](intent://local/task/t-complete)\n- [B](intent://local/task/t-progress)\n\
         - [C](intent://local/task/t-review)\n- [D](intent://local/task/t-cancelled)\n\
         - [E](intent://local/task/t-open)\n- [G](intent://local/task/t-ghost)",
    );
    store.insert_note(&spec).await.expect("spec");
    for (id, status) in [
        ("t-complete", TaskStatus::Complete),
        ("t-progress", TaskStatus::InProgress),
        ("t-review", TaskStatus::ReviewRequired),
        ("t-cancelled", TaskStatus::Cancelled),
        ("t-open", TaskStatus::NotStarted),
        ("t-unlinked", TaskStatus::Complete), // spec child but not linked
    ] {
        store
            .insert_note(&mk_task(&ws1, id, Some("spec"), status))
            .await
            .unwrap();
    }
    store
        .insert_note(&mk_task(&ws1, "t-orphan", None, TaskStatus::Complete))
        .await
        .unwrap();
    store
        .insert_note(&mk_task(
            &ws1,
            "t-other-parent",
            Some("t-open"),
            TaskStatus::Complete,
        ))
        .await
        .unwrap();
    let mut plain_child = note(&ws1, "n-plain", "no task metadata");
    plain_child.parent_id = Some(NoteId::from("spec"));
    store.insert_note(&plain_child).await.unwrap();

    // Case 2: spec without links — backward-compat fallback counts all direct
    // children with task metadata.
    let ws2 = WorkspaceId::new();
    store.insert_workspace(&workspace(&ws2)).await.expect("ws2");
    store
        .insert_note(&note(&ws2, "spec", "no task links here"))
        .await
        .unwrap();
    for (id, status) in [
        ("u-complete", TaskStatus::Complete),
        ("u-waiting", TaskStatus::Waiting),
        ("u-cancelled", TaskStatus::Cancelled),
        ("u-review", TaskStatus::ReviewRequired),
    ] {
        store
            .insert_note(&mk_task(&ws2, id, Some("spec"), status))
            .await
            .unwrap();
    }

    // Case 3: no spec note at all — direct spec children can't exist, so both
    // paths must report zeros even with a stray task note present.
    let ws3 = WorkspaceId::new();
    store.insert_workspace(&workspace(&ws3)).await.expect("ws3");
    store
        .insert_note(&mk_task(&ws3, "v-stray", None, TaskStatus::Complete))
        .await
        .unwrap();

    for ws in [&ws1, &ws2, &ws3] {
        let notes = store.list_notes(ws).await.expect("list notes");
        let enriched = crate::compute_task_stats(&notes);
        let cheap = store.count_task_stats(ws).await.expect("cheap stats");
        assert_eq!(cheap, enriched, "parity failed for workspace {ws:?}");
    }

    // Spot-check the expected counts and the services-side helper.
    let svc = Services::new(store);
    let s1 = svc.cheap_task_stats(&ws1).await.expect("ws1 stats");
    assert_eq!((s1.total, s1.completed, s1.in_progress), (4, 1, 2));
    let s2 = svc.cheap_task_stats(&ws2).await.expect("ws2 stats");
    assert_eq!((s2.total, s2.completed, s2.in_progress), (3, 1, 1));
    let s3 = svc.cheap_task_stats(&ws3).await.expect("ws3 stats");
    assert_eq!((s3.total, s3.completed, s3.in_progress), (0, 0, 0));
}

/// The lite list path (workspace.subscribe seq-0 snapshot) is self-sufficient
/// for client status rendering: rows carry `taskStats` (cheap counting query),
/// `displayStatus` (same derivation as the enriched path — a subsequent
/// enriched `workspace.get` must agree for the same data), and `cowSupported`,
/// while continuing to omit `agentSummary`/`diffSummary`. The lite read also
/// seeds the `last_display_statuses` baseline (a seed never emits).
#[tokio::test]
async fn lite_list_is_self_sufficient_for_status_rendering() {
    use intent_core::{TaskMetadata, TaskStatus, WorkspaceDisplayStatus};

    let tmp = TempDb::new();
    let store = Store::open(&tmp.path).await.expect("open store");
    let root = WorkspacesRoot::new();
    let svc = Services::new(store.clone()).with_workspaces_root(root.path().to_path_buf());

    let ws = WorkspaceId::new();
    store.insert_workspace(&workspace(&ws)).await.expect("ws");
    store
        .insert_note(&note(&ws, "spec", "no task links here"))
        .await
        .expect("spec");
    for (id, status) in [
        ("t-progress", TaskStatus::InProgress),
        ("t-complete", TaskStatus::Complete),
        ("t-open", TaskStatus::NotStarted),
    ] {
        let mut tn = note(&ws, id, "body");
        tn.parent_id = Some(NoteId::from("spec"));
        tn.metadata.task = Some(TaskMetadata {
            status,
            ..Default::default()
        });
        store.insert_note(&tn).await.expect("task note");
    }

    let list = svc.list_workspaces_lite(true).await.expect("lite list");
    let row = list.iter().find(|w| w.id == ws).expect("row in lite list");
    let stats = row.task_stats.as_ref().expect("taskStats populated");
    assert_eq!((stats.total, stats.completed, stats.in_progress), (3, 1, 1));
    // No agent is running, so the task-stage rollup demotes to idle.
    assert_eq!(row.display_status, Some(WorkspaceDisplayStatus::Idle));
    assert!(row.cow_supported.is_some(), "cowSupported populated");
    assert!(row.agent_summary.is_none(), "agentSummary omitted");
    assert!(row.diff_summary.is_none(), "diffSummary omitted");

    // Parity with the enriched read for the same data.
    let enriched = svc.get_workspace(ws.clone()).await.expect("enriched get");
    assert_eq!(row.display_status, enriched.display_status);
    assert_eq!(row.task_stats, enriched.task_stats);

    // Wire shape: cheap aggregates present, heavy aggregates absent.
    let v = serde_json::to_value(row).unwrap();
    assert_eq!(v["displayStatus"], "idle");
    assert_eq!(v["taskStats"]["total"], 3);
    assert!(v["cowSupported"].is_boolean());
    assert!(v.get("agentSummary").is_none());
    assert!(v.get("diffSummary").is_none());

    // The lite read seeded the displayStatus baseline map.
    let seeded = svc.last_display_statuses.contains(&ws);
    assert!(seeded, "lite list must seed the displayStatus baseline");
}

/// Both list emit paths (`workspace.list` and the lite path behind
/// `workspace.subscribe` seq-0) merge externally known PRs into each row's
/// `pullRequests`: git-root PRs (`workspace_git_root.pull_requests`) and
/// monitor-derived PRs (active + completed; cancelled excluded), deduped by
/// URL with workspace > git-root > monitor priority. Purely an emit-path
/// merge — nothing is persisted, and a row with no external sources keeps
/// its stored value untouched.
#[tokio::test]
async fn list_paths_merge_git_root_and_monitor_prs_into_pull_requests() {
    use intent_core::{
        PrMonitor, PrMonitorId, PrMonitorState, PullRequestInfo, PullRequestStatus,
        WorkspaceGitRoot, WorkspaceGitRootId, WorkspaceGitRootSource,
    };

    let tmp = TempDb::new();
    let store = Store::open(&tmp.path).await.expect("open store");
    let root = WorkspacesRoot::new();

    let pr_info = |number: u64, url: &str, title: &str| PullRequestInfo {
        id: number.to_string(),
        number,
        url: url.to_string(),
        title: title.to_string(),
        status: PullRequestStatus::Open,
        created_at: "2026-01-01T00:00:00Z".into(),
        updated_at: "2026-01-01T00:00:00Z".into(),
        base_ref: None,
        head_ref: None,
        head_sha: None,
        author: None,
        mergeable: None,
        mergeable_state: None,
        is_draft: None,
    };
    let git_root = |ws: &WorkspaceId, path: &str, prs: Vec<PullRequestInfo>| {
        let ts = now_iso();
        WorkspaceGitRoot {
            id: WorkspaceGitRootId::new(),
            workspace_id: ws.clone(),
            path: path.to_string(),
            source: WorkspaceGitRootSource::Agent,
            repo_owner: Some("o".into()),
            repo_name: Some("r".into()),
            registered_by_agent_ids: vec![],
            registered_commit_sha: None,
            pr_number: None,
            pr_url: None,
            pr_status: None,
            pull_requests: Some(prs),
            created_at: ts.clone(),
            updated_at: ts,
        }
    };
    let monitor = |ws: &WorkspaceId,
                   owner: &str,
                   name: &str,
                   number: i64,
                   state: PrMonitorState,
                   snapshot: Option<String>| {
        PrMonitor {
            monitor_id: PrMonitorId::new(),
            workspace_id: ws.clone(),
            agent_id: AgentId::from("agent-mon"),
            repo_owner: owner.to_string(),
            repo_name: name.to_string(),
            pr_number: number,
            state,
            last_snapshot: snapshot,
            baseline_snapshot: None,
            pending_changes: vec![],
            pending_since: None,
            last_change_at: None,
            last_polled_at: None,
            last_error: None,
            created_at: "2026-01-02T00:00:00Z".into(),
            updated_at: "2026-01-02T00:00:01Z".into(),
        }
    };

    // ws1: NULL workspace PRs; one git-root PR, one snapshot-backed active
    // monitor, one snapshotless completed monitor, one cancelled monitor
    // (excluded), and a monitor duplicating the git-root PR's URL (deduped).
    let ws1 = WorkspaceId::new();
    store.insert_workspace(&workspace(&ws1)).await.expect("ws1");
    // Monitor rows FK onto agent_session; one session covers every monitor.
    let session = AgentSession {
        harness_version: intent_core::CURRENT_HARNESS_VERSION.to_string(),
        harness_features: None,
        id: AgentId::from("agent-mon"),
        workspace_id: ws1.clone(),
        parent_agent_id: None,
        backend_session_id: None,
        acp_session_id: None,
        name: "Monitor Owner".into(),
        name_explicitly_set: true,
        model: None,
        reasoning_effort: None,
        effort_levels: None,
        provider: None,
        system_prompt: None,
        specialist: None,
        status: AgentStatus::Active,
        is_active: true,
        messages: vec![],
        stats: None,
        task_note_id: None,
        skip_auto_commit: false,
        completion_report: None,
        completion_report_timestamp: None,
        attention_request_kind: None,
        attention_request_reason: None,
        attention_request_timestamp: None,
        delegation_depth: None,
        initial_message: None,
        context_references: None,
        image_blocks: None,
        file_blocks: None,
        is_background: false,
        metadata: None,
        created_at: now_iso(),
        updated_at: now_iso(),
        sandbox_id: None,
        sandbox_path: None,
        sandbox_branch: None,
        stop_reason: None,
        stop_reason_timestamp: None,
        session_corrupted: false,
        pending_delete_at: None,
        retired_at: None,
    };
    store.insert_agent_session(&session).await.expect("session");

    store
        .upsert_workspace_git_root(&git_root(
            &ws1,
            "/tmp/root-a",
            vec![pr_info(1, "https://github.com/o/r/pull/1", "Root PR")],
        ))
        .await
        .expect("ws1 root");
    let snapshot_b = serde_json::json!({
        "title": "Monitored PR",
        "url": "https://github.com/o/r/pull/2",
        "headSha": "abc123",
        "conversationCount": 0,
        "reviewCommentCount": 0,
        "requirements": {
            "state": "open",
            "isDraft": false,
            "hasConflicts": false,
            "isBehind": false,
            "mergeable": true,
            "checks": {
                "total": 0, "passed": 0, "failed": 0, "pending": 0,
                "items": [], "failingRequired": [], "pendingRequired": [],
                "requiredKnown": true
            },
            "approvals": { "decision": "none", "have": 0, "changesRequested": 0 },
            "threads": { "unresolved": 0 },
            "rulesKnown": false
        }
    })
    .to_string();
    for m in [
        monitor(&ws1, "o", "r", 2, PrMonitorState::Active, Some(snapshot_b)),
        monitor(&ws1, "o2", "r2", 7, PrMonitorState::Completed, None),
        monitor(&ws1, "o", "r", 9, PrMonitorState::Cancelled, None),
        // Snapshotless monitor on PR 1: synthesized URL duplicates the
        // git-root entry, so the richer git-root entry wins.
        monitor(&ws1, "o", "r", 1, PrMonitorState::Active, None),
    ] {
        store.insert_pr_monitor(&m).await.expect("monitor");
    }

    // ws2: the workspace's own entry wins over a same-URL git-root entry.
    let ws2 = WorkspaceId::new();
    let mut w2 = workspace(&ws2);
    w2.pull_requests = Some(vec![pr_info(
        5,
        "https://github.com/o/r/pull/5",
        "Workspace copy",
    )]);
    store.insert_workspace(&w2).await.expect("ws2");
    store
        .upsert_workspace_git_root(&git_root(
            &ws2,
            "/tmp/root-b",
            vec![
                pr_info(5, "https://github.com/o/r/pull/5", "Root copy"),
                pr_info(6, "https://github.com/o/r/pull/6", "Root-only PR"),
            ],
        ))
        .await
        .expect("ws2 root");

    // ws3: no external sources — the stored (NULL) value stays untouched.
    let ws3 = WorkspaceId::new();
    store.insert_workspace(&workspace(&ws3)).await.expect("ws3");

    // ws4: a git root with an EMPTY pull_requests list contributes nothing —
    // the stored NULL must not become `[]` on the wire.
    let ws4 = WorkspaceId::new();
    store.insert_workspace(&workspace(&ws4)).await.expect("ws4");
    store
        .upsert_workspace_git_root(&git_root(&ws4, "/tmp/root-c", vec![]))
        .await
        .expect("ws4 root");

    // ws5: archived, with a git-root PR and a monitor — merged only when the
    // list call includes archived workspaces.
    let ws5 = WorkspaceId::new();
    let mut w5 = workspace(&ws5);
    w5.archived = true;
    w5.status = intent_core::WorkspaceStatus::Archived;
    store.insert_workspace(&w5).await.expect("ws5");
    store
        .upsert_workspace_git_root(&git_root(
            &ws5,
            "/tmp/root-d",
            vec![pr_info(
                8,
                "https://github.com/o/r/pull/8",
                "Archived root PR",
            )],
        ))
        .await
        .expect("ws5 root");

    let svc = Services::new(store.clone()).with_workspaces_root(root.path().to_path_buf());

    let assert_merged = |list: &[Workspace], path: &str| {
        let r1 = list.iter().find(|w| w.id == ws1).expect("ws1 row");
        let prs = r1.pull_requests.as_ref().expect("ws1 pullRequests");
        let urls: Vec<_> = prs.iter().map(|p| p.url.as_str()).collect();
        assert_eq!(
            urls,
            [
                "https://github.com/o/r/pull/1",
                "https://github.com/o/r/pull/2",
                "https://github.com/o2/r2/pull/7",
            ],
            "{path}: git-root first, then monitor-derived; cancelled + dup excluded"
        );
        // Git-root entry beat the snapshotless duplicate monitor on PR 1.
        assert_eq!(prs[0].title, "Root PR", "{path}");
        // Snapshot-backed monitor entry: fields synthesized off the snapshot.
        assert_eq!(prs[1].title, "Monitored PR", "{path}");
        assert_eq!(prs[1].number, 2, "{path}");
        assert_eq!(
            prs[1].status,
            intent_core::PullRequestStatus::Open,
            "{path}"
        );
        assert_eq!(prs[1].head_sha.as_deref(), Some("abc123"), "{path}");
        assert_eq!(prs[1].is_draft, Some(false), "{path}");
        // Snapshotless completed monitor: URL/title synthesized from the
        // repo identity; terminal without a verdict reads closed, not merged.
        assert_eq!(prs[2].title, "o2/r2#7", "{path}");
        assert_eq!(
            prs[2].status,
            intent_core::PullRequestStatus::Closed,
            "{path}"
        );

        let r2 = list.iter().find(|w| w.id == ws2).expect("ws2 row");
        let prs2 = r2.pull_requests.as_ref().expect("ws2 pullRequests");
        assert_eq!(prs2.len(), 2, "{path}: same-URL root entry deduped");
        assert_eq!(prs2[0].title, "Workspace copy", "{path}: workspace wins");
        assert_eq!(prs2[1].title, "Root-only PR", "{path}");
        // The merged list is a plain array on the wire.
        let v = serde_json::to_value(r2).unwrap();
        assert!(v["pullRequests"].is_array(), "{path}");

        let r3 = list.iter().find(|w| w.id == ws3).expect("ws3 row");
        assert!(
            r3.pull_requests.is_none(),
            "{path}: no external sources leaves the stored value untouched"
        );

        // Empty git-root list: stored NULL stays omitted on the wire.
        let r4 = list.iter().find(|w| w.id == ws4).expect("ws4 row");
        assert!(
            r4.pull_requests.is_none(),
            "{path}: empty git-root list must not materialize []"
        );
        let v4 = serde_json::to_value(r4).unwrap();
        assert!(
            v4.get("pullRequests").is_none(),
            "{path}: pullRequests omitted, not []"
        );
    };

    let full = svc.list_workspaces(false).await.expect("full list");
    assert_merged(&full, "workspace.list");
    let lite = svc.list_workspaces_lite(false).await.expect("lite list");
    assert_merged(&lite, "lite list");

    // Archived-inclusive list: the archived row's git-root PR merges in.
    let all = svc.list_workspaces_lite(true).await.expect("archived list");
    let r5 = all.iter().find(|w| w.id == ws5).expect("ws5 row");
    let prs5 = r5.pull_requests.as_ref().expect("ws5 pullRequests");
    assert_eq!(prs5.len(), 1);
    assert_eq!(prs5[0].title, "Archived root PR");

    // Archived-excluding bulk reads filter archived-workspace rows in SQL.
    let roots = store
        .list_workspace_git_roots_with_prs(false)
        .await
        .expect("roots");
    assert!(
        roots.iter().all(|r| r.workspace_id != ws5),
        "archived workspace's roots excluded from the non-archived read"
    );

    // Emit-path only: nothing was persisted back to workspace.pull_requests.
    let stored = store.get_workspace(&ws1).await.expect("ws1 stored");
    assert!(stored.pull_requests.is_none(), "merge must not persist");
}

/// The emit-path PR merge moves a stale entry's status up the lifecycle
/// ladder (open/draft < closed < merged) when a lower-priority duplicate
/// ranks higher: a git-root entry still reading `open`/`draft`/`closed`
/// flips to `merged` when the monitor's snapshot saw the PR merge (status +
/// updatedAt + isDraft; identity fields keep the git-root entry — a
/// `draft` entry upgraded to a terminal status must not keep claiming
/// `isDraft: true`), while a git-root entry already `merged` is never
/// downgraded by the snapshotless completed-monitor `closed` fallback
/// (intent-hq/monorepo#3127).
#[tokio::test]
async fn merged_pr_pool_status_ladder_upgrades_stale_entries() {
    use intent_core::{
        PrMonitor, PrMonitorId, PrMonitorState, PullRequestInfo, PullRequestStatus,
        WorkspaceGitRoot, WorkspaceGitRootId, WorkspaceGitRootSource,
    };

    let tmp = TempDb::new();
    let store = Store::open(&tmp.path).await.expect("open store");
    let root = WorkspacesRoot::new();

    let pr_info =
        |number: u64, url: &str, title: &str, status: PullRequestStatus| PullRequestInfo {
            id: number.to_string(),
            number,
            url: url.to_string(),
            title: title.to_string(),
            status,
            created_at: "2026-01-01T00:00:00Z".into(),
            updated_at: "2026-01-01T00:00:00Z".into(),
            base_ref: None,
            head_ref: None,
            head_sha: None,
            author: None,
            mergeable: None,
            mergeable_state: None,
            is_draft: None,
        };
    let monitor =
        |ws: &WorkspaceId, number: i64, state: PrMonitorState, snapshot: Option<String>| {
            PrMonitor {
                monitor_id: PrMonitorId::new(),
                workspace_id: ws.clone(),
                agent_id: AgentId::from("agent-mon"),
                repo_owner: "o".into(),
                repo_name: "r".into(),
                pr_number: number,
                state,
                last_snapshot: snapshot,
                baseline_snapshot: None,
                pending_changes: vec![],
                pending_since: None,
                last_change_at: None,
                last_polled_at: None,
                last_error: None,
                created_at: "2026-01-02T00:00:00Z".into(),
                updated_at: "2026-01-02T00:00:01Z".into(),
            }
        };

    let ws = WorkspaceId::new();
    store.insert_workspace(&workspace(&ws)).await.expect("ws");
    let session = AgentSession {
        harness_version: intent_core::CURRENT_HARNESS_VERSION.to_string(),
        harness_features: None,
        id: AgentId::from("agent-mon"),
        workspace_id: ws.clone(),
        parent_agent_id: None,
        backend_session_id: None,
        acp_session_id: None,
        name: "Monitor Owner".into(),
        name_explicitly_set: true,
        model: None,
        reasoning_effort: None,
        effort_levels: None,
        provider: None,
        system_prompt: None,
        specialist: None,
        status: AgentStatus::Active,
        is_active: true,
        messages: vec![],
        stats: None,
        task_note_id: None,
        skip_auto_commit: false,
        completion_report: None,
        completion_report_timestamp: None,
        attention_request_kind: None,
        attention_request_reason: None,
        attention_request_timestamp: None,
        delegation_depth: None,
        initial_message: None,
        context_references: None,
        image_blocks: None,
        file_blocks: None,
        is_background: false,
        metadata: None,
        created_at: now_iso(),
        updated_at: now_iso(),
        sandbox_id: None,
        sandbox_path: None,
        sandbox_branch: None,
        stop_reason: None,
        stop_reason_timestamp: None,
        session_corrupted: false,
        pending_delete_at: None,
        retired_at: None,
    };
    store.insert_agent_session(&session).await.expect("session");

    // Git root: PR 1 stale-open (the sweep hasn't seen the merge yet),
    // PR 3 already merged, PR 4 stale-draft, PR 5 stale-closed.
    let mut stale_draft = pr_info(
        4,
        "https://github.com/o/r/pull/4",
        "Stale draft",
        PullRequestStatus::Draft,
    );
    stale_draft.is_draft = Some(true);
    store
        .upsert_workspace_git_root(&WorkspaceGitRoot {
            id: WorkspaceGitRootId::new(),
            workspace_id: ws.clone(),
            path: "/tmp/root-a".into(),
            source: WorkspaceGitRootSource::Agent,
            repo_owner: Some("o".into()),
            repo_name: Some("r".into()),
            registered_by_agent_ids: vec![],
            registered_commit_sha: None,
            pr_number: None,
            pr_url: None,
            pr_status: None,
            pull_requests: Some(vec![
                pr_info(
                    1,
                    "https://github.com/o/r/pull/1",
                    "Stale open",
                    PullRequestStatus::Open,
                ),
                pr_info(
                    3,
                    "https://github.com/o/r/pull/3",
                    "Already merged",
                    PullRequestStatus::Merged,
                ),
                stale_draft,
                pr_info(
                    5,
                    "https://github.com/o/r/pull/5",
                    "Stale closed",
                    PullRequestStatus::Closed,
                ),
            ]),
            created_at: now_iso(),
            updated_at: now_iso(),
        })
        .await
        .expect("git root");

    // Monitors whose snapshots saw PRs 1, 4 and 5 merge, plus a snapshotless
    // completed monitor on PR 3 (synthesized URL duplicates the git-root
    // entry; its `closed` fallback carries no merged/closed verdict).
    let merged_snapshot = |number: u64, title: &str| {
        serde_json::json!({
            "title": title,
            "url": format!("https://github.com/o/r/pull/{number}"),
            "conversationCount": 0,
            "reviewCommentCount": 0,
            "requirements": {
                "state": "merged",
                "isDraft": false,
                "hasConflicts": false,
                "isBehind": false,
                "checks": {
                    "total": 0, "passed": 0, "failed": 0, "pending": 0,
                    "items": [], "failingRequired": [], "pendingRequired": [],
                    "requiredKnown": true
                },
                "approvals": { "decision": "none", "have": 0, "changesRequested": 0 },
                "threads": { "unresolved": 0 },
                "rulesKnown": false
            }
        })
        .to_string()
    };
    for m in [
        monitor(
            &ws,
            1,
            PrMonitorState::Completed,
            Some(merged_snapshot(1, "Stale open")),
        ),
        monitor(&ws, 3, PrMonitorState::Completed, None),
        monitor(
            &ws,
            4,
            PrMonitorState::Completed,
            Some(merged_snapshot(4, "Stale draft")),
        ),
        monitor(
            &ws,
            5,
            PrMonitorState::Completed,
            Some(merged_snapshot(5, "Stale closed")),
        ),
    ] {
        store.insert_pr_monitor(&m).await.expect("monitor");
    }

    let svc = Services::new(store.clone()).with_workspaces_root(root.path().to_path_buf());

    for (list, path) in [
        (
            svc.list_workspaces(false).await.expect("full list"),
            "workspace.list",
        ),
        (
            svc.list_workspaces_lite(false).await.expect("lite list"),
            "lite list",
        ),
    ] {
        let row = list.iter().find(|w| w.id == ws).expect("ws row");
        let prs = row.pull_requests.as_ref().expect("pullRequests");
        assert_eq!(prs.len(), 4, "{path}: URL dedup keeps one entry per PR");
        // Stale-open git-root entry: the monitor's merged verdict wins the
        // lifecycle fields (status, updatedAt, isDraft), git-root keeps the
        // identity fields.
        assert_eq!(prs[0].url, "https://github.com/o/r/pull/1", "{path}");
        assert_eq!(prs[0].title, "Stale open", "{path}: git-root fields kept");
        assert_eq!(
            prs[0].status,
            intent_core::PullRequestStatus::Merged,
            "{path}: monitor's merged verdict overrides the stale open status"
        );
        assert_eq!(
            prs[0].updated_at, "2026-01-02T00:00:01Z",
            "{path}: updatedAt follows the status upgrade"
        );
        // Already-merged git-root entry: the completed monitor's `closed`
        // fallback must not downgrade the merged verdict.
        assert_eq!(prs[1].url, "https://github.com/o/r/pull/3", "{path}");
        assert_eq!(
            prs[1].status,
            intent_core::PullRequestStatus::Merged,
            "{path}: closed fallback never downgrades a merged entry"
        );
        assert_eq!(
            prs[1].updated_at, "2026-01-01T00:00:00Z",
            "{path}: terminal entry untouched"
        );
        // Stale-draft git-root entry: isDraft moves with the status so the
        // upgraded entry can't read merged while still claiming draft.
        assert_eq!(prs[2].url, "https://github.com/o/r/pull/4", "{path}");
        assert_eq!(
            prs[2].status,
            intent_core::PullRequestStatus::Merged,
            "{path}: monitor's merged verdict overrides the stale draft status"
        );
        assert_eq!(
            prs[2].is_draft,
            Some(false),
            "{path}: isDraft follows the status upgrade"
        );
        // Stale-closed git-root entry: merged is irreversible, so it
        // overrides even a terminal `closed`.
        assert_eq!(prs[3].url, "https://github.com/o/r/pull/5", "{path}");
        assert_eq!(
            prs[3].status,
            intent_core::PullRequestStatus::Merged,
            "{path}: merged verdict overrides a stale closed status"
        );
        assert_eq!(
            prs[3].updated_at, "2026-01-02T00:00:01Z",
            "{path}: updatedAt follows the closed→merged upgrade"
        );
    }
}

/// `crossWorkspace.listSiblings` returns only same-`repositoryPath` peers
/// (self filtered out, other-repo filtered out) with the `PascalCase` status.
#[tokio::test]
async fn cross_workspace_list_siblings_scopes_to_repository() {
    let tmp = TempDb::new();
    let store = Store::open(&tmp.path).await.expect("open store");

    let mk = |id: &WorkspaceId, title: &str, repo: Option<&str>| {
        let mut w = workspace(id);
        w.title = title.to_string();
        w.repository_path = repo.map(str::to_string);
        w
    };

    let caller = WorkspaceId::from("ws-caller");
    let sibling = WorkspaceId::from("ws-sibling");
    let other_repo = WorkspaceId::from("ws-other");
    let no_repo = WorkspaceId::from("ws-norepo");
    store
        .insert_workspace(&mk(&caller, "Caller", Some("/repo/a")))
        .await
        .unwrap();
    store
        .insert_workspace(&mk(&sibling, "", Some("/repo/a")))
        .await
        .unwrap();
    store
        .insert_workspace(&mk(&other_repo, "Other", Some("/repo/b")))
        .await
        .unwrap();
    store
        .insert_workspace(&mk(&no_repo, "NoRepo", None))
        .await
        .unwrap();

    let svc = Services::new(store);
    let v = svc
        .cross_workspace_list_siblings(caller.clone())
        .await
        .expect("siblings");
    let arr = v.as_array().expect("array");
    assert_eq!(arr.len(), 1);
    assert_eq!(arr[0]["id"], "ws-sibling");
    // Empty title falls back to "Untitled"; status is PascalCase.
    assert_eq!(arr[0]["title"], "Untitled");
    assert_eq!(arr[0]["status"], "Active");
    assert!(arr[0]["createdAt"].is_string());
}

/// A caller with no `repositoryPath` cannot list siblings (mirrors the TS
