    // reference ambiguous: warn and skip rather than guess.
    let content = "@@@task\n# Dup\nbody\n@@@\n\
                   @@@task\n# Dup\nmore\n@@@\n\
                   @@@task dependsOn=Dup\n# Consumer\nbody\n@@@";
