    /// An agent-context `file.delete` records a `deleted` attribution row for
    /// the caller (monorepo#939); a no-agent-context delete records none.
    #[tokio::test]
    async fn file_delete_agent_context_attribution() {
        let repo = init_git_repo();
        let (_t, svc, ws) = svc_with_repo(&repo).await;
        commit_file(&repo.dir, "doomed.txt", "to be deleted\n", "add doomed");
        commit_file(&repo.dir, "user-doomed.txt", "user file\n", "add user file");

        svc.file_delete(
            ws.clone(),
            "doomed.txt".to_string(),
            Some(AgentId::from("agent-d1")),
        )
        .await
        .unwrap();
        svc.file_delete(ws.clone(), "user-doomed.txt".to_string(), None)
            .await
            .unwrap();

        let rows = svc.store().list_tracked_changes(&ws).await.unwrap();
        let row = rows
            .iter()
            .find(|r| r.path == "doomed.txt")
            .expect("attribution row recorded for agent delete");
        assert_eq!(row.stage, "unstaged");
        assert_eq!(row.status, "deleted");
        assert_eq!(row.agent_id.as_deref(), Some("agent-d1"));
        assert!(
            !rows.iter().any(|r| r.path == "user-doomed.txt"),
            "no attribution for a userless delete: {rows:?}"
        );
    }

    /// An agent-context `file.rename` records both sides — old path `deleted`,
    /// new path `added` — attributed to the caller (monorepo#939), and the
    /// attribution-filtered fallback commits the rename. A no-agent-context
    /// rename records none.
    #[tokio::test]
    async fn file_rename_agent_context_attribution() {
        let repo = init_git_repo();
        let (_t, svc, ws) = svc_with_repo(&repo).await;
        commit_file(&repo.dir, "old-name.txt", "contents\n", "add old-name");

        svc.file_rename(
            ws.clone(),
            "old-name.txt".to_string(),
            "new-name.txt".to_string(),
            Some(AgentId::from("agent-r1")),
        )
        .await
        .unwrap();

        let rows = svc.store().list_tracked_changes(&ws).await.unwrap();
        let old_row = rows
            .iter()
            .find(|r| r.path == "old-name.txt")
            .expect("old-path attribution row recorded");
        assert_eq!(old_row.status, "deleted");
        assert_eq!(old_row.agent_id.as_deref(), Some("agent-r1"));
        let new_row = rows
            .iter()
            .find(|r| r.path == "new-name.txt")
            .expect("new-path attribution row recorded");
        assert_eq!(new_row.status, "added");
        assert_eq!(new_row.agent_id.as_deref(), Some("agent-r1"));

        // The attribution-filtered fallback commits both sides of the rename.
        let r = svc
            .git_agent_commit(
                ws.clone(),
                "agent rename".to_string(),
                Some(AgentId::from("agent-r1")),
                None,
                None,
                false,
                None,
            )
            .await
            .unwrap();
        assert!(
            r.files.contains(&"old-name.txt".to_string())
                && r.files.contains(&"new-name.txt".to_string()),
            "both rename sides committed: {:?}",
            r.files
        );
    }

    /// A `file.rename` without an agent caller context records no attribution.
    #[tokio::test]
    async fn file_rename_without_agent_context_records_no_attribution() {
        let repo = init_git_repo();
        let (_t, svc, ws) = svc_with_repo(&repo).await;
        commit_file(&repo.dir, "before.txt", "contents\n", "add before");

        svc.file_rename(
            ws.clone(),
            "before.txt".to_string(),
            "after.txt".to_string(),
            None,
        )
        .await
        .unwrap();

        let rows = svc.store().list_tracked_changes(&ws).await.unwrap();
        assert!(
            rows.is_empty(),
            "no attribution for a userless rename: {rows:?}"
        );
        assert!(repo.dir.join("after.txt").exists(), "file was renamed");
    }

    /// `upsert_tracked_change` keys rows on `(workspace, path, stage, agent)`
    /// (monorepo#957): a second agent touching the same path gets its own row
    /// instead of overwriting the first agent's attribution, and re-upserting
    /// for an agent updates that agent's row in place.
    #[tokio::test]
    async fn upsert_tracked_change_keeps_rows_per_agent() {
        let (_t, svc, ws) = ft_setup().await;
        svc.store()
            .upsert_tracked_change(&tracked(&ws, "x.txt", "unstaged", Some("agent-a")))
            .await
            .unwrap();
        svc.store()
            .upsert_tracked_change(&tracked(&ws, "x.txt", "unstaged", Some("agent-b")))
            .await
            .unwrap();
        // Unattributed pipeline rows key separately from agent rows too.
        svc.store()
            .upsert_tracked_change(&tracked(&ws, "x.txt", "unstaged", None))
            .await
            .unwrap();

        let rows = svc.store().list_tracked_changes(&ws).await.unwrap();
        assert_eq!(rows.len(), 3, "one row per agent (and the null row)");

        // Same-agent re-upsert updates in place (no fourth row).
        let mut again = tracked(&ws, "x.txt", "unstaged", Some("agent-a"));
        again.additions = 9;
        let prev = svc.store().upsert_tracked_change(&again).await.unwrap();
        assert_eq!(prev, Some((5, 2)), "replaced agent-a's own counters");
        let rows = svc.store().list_tracked_changes(&ws).await.unwrap();
        assert_eq!(rows.len(), 3);
        let a = rows
            .iter()
            .find(|r| r.agent_id.as_deref() == Some("agent-a"))
            .unwrap();
        assert_eq!(a.additions, 9);
        let b = rows
            .iter()
            .find(|r| r.agent_id.as_deref() == Some("agent-b"))
            .unwrap();
        assert_eq!(b.additions, 5, "agent-b's row untouched");
    }

    /// Shared-path regression (monorepo#957): agent A edits x.txt, agent B
    /// later touches the same file. A's no-`files` fallback commit still
    /// includes x.txt (A's attribution row survives B's touch), and the
    /// commit — which captures the file's full working-tree content, i.e.
    /// both agents' edits — advances BOTH agents' rows to `committed`.
    #[tokio::test]
    async fn agent_commit_shared_path_includes_first_agents_edit() {
        let repo = init_git_repo();
        let (_t, svc, ws) = svc_with_repo(&repo).await;
        std::fs::write(repo.dir.join("x.txt"), "A then B\n").unwrap();
        svc.store()
            .upsert_tracked_change(&tracked(&ws, "x.txt", "unstaged", Some("agent-a")))
            .await
            .unwrap();
        svc.store()
            .upsert_tracked_change(&tracked(&ws, "x.txt", "unstaged", Some("agent-b")))
            .await
            .unwrap();

        let r = svc
            .git_agent_commit(
                ws.clone(),
                "agent a work".to_string(),
                Some(AgentId::from("agent-a")),
                None,
                None,
                false,
                None,
            )
            .await
            .unwrap();
        assert_eq!(r.files, vec!["x.txt".to_string()], "A's edit not dropped");

        // The commit satisfied both agents' attribution: every row advanced.
        let rows = svc.store().list_tracked_changes(&ws).await.unwrap();
        for agent in ["agent-a", "agent-b"] {
            let row = rows
                .iter()
                .find(|r| r.agent_id.as_deref() == Some(agent))
                .unwrap();
            assert_eq!(row.stage, "committed", "{agent}'s row advanced");
        }
    }

    /// Clearing semantics (monorepo#957): after A's commit of the shared path,
    /// B's fallback commit does NOT spuriously re-commit it (B's satisfied row
    /// was advanced with A's), but a fresh edit by B re-attributes the path
    /// and B's next fallback commit includes it.
    #[tokio::test]
    async fn agent_commit_shared_path_cleared_rows_not_recommitted() {
        let repo = init_git_repo();
        let (_t, svc, ws) = svc_with_repo(&repo).await;
        std::fs::write(repo.dir.join("x.txt"), "A then B\n").unwrap();
        svc.store()
            .upsert_tracked_change(&tracked(&ws, "x.txt", "unstaged", Some("agent-a")))
            .await
            .unwrap();
        svc.store()
            .upsert_tracked_change(&tracked(&ws, "x.txt", "unstaged", Some("agent-b")))
            .await
            .unwrap();
        svc.git_agent_commit(
            ws.clone(),
            "agent a work".to_string(),
            Some(AgentId::from("agent-a")),
            None,
            None,
            false,
            None,
        )
        .await
        .unwrap();

        // B has nothing uncommitted left → silent-skip error, no new commit.
        let err = svc
            .git_agent_commit(
                ws.clone(),
                "agent b follow-up".to_string(),
                Some(AgentId::from("agent-b")),
                None,
                None,
                false,
                None,
            )
            .await
            .unwrap_err();
        assert!(
            format!("{err}").contains("No uncommitted changes found for this agent"),
            "got: {err}"
        );
        assert_eq!(intent_git::history::history(&repo.dir, 5).unwrap().len(), 2);

        // B edits the file again → a fresh unstaged row → B's commit takes it.
        std::fs::write(repo.dir.join("x.txt"), "A then B then B again\n").unwrap();
        svc.store()
            .upsert_tracked_change(&tracked(&ws, "x.txt", "unstaged", Some("agent-b")))
            .await
            .unwrap();
        let r = svc
            .git_agent_commit(
                ws,
                "agent b again".to_string(),
                Some(AgentId::from("agent-b")),
                None,
                None,
                false,
                None,
            )
            .await
            .unwrap();
        assert_eq!(r.files, vec!["x.txt".to_string()]);
    }

    /// Directory-rename regression (monorepo#957): an agent-context
    /// `file.rename` of a DIRECTORY records per-file attribution rows for
    /// every moved path (old side `deleted`, new side `added`), so the
    /// attribution-filtered fallback commit includes the whole move.
    #[tokio::test]
    async fn file_rename_directory_records_attribution_for_all_moved_files() {
        let repo = init_git_repo();
        let (_t, svc, ws) = svc_with_repo(&repo).await;
        std::fs::create_dir_all(repo.dir.join("dir/sub")).unwrap();
        commit_file(&repo.dir, "dir/a.txt", "a\n", "add dir/a");
        commit_file(&repo.dir, "dir/sub/b.txt", "b\n", "add dir/sub/b");

        svc.file_rename(
            ws.clone(),
            "dir".to_string(),
            "moved".to_string(),
            Some(AgentId::from("agent-r2")),
        )
        .await
        .unwrap();

        let rows = svc.store().list_tracked_changes(&ws).await.unwrap();
        let row = |path: &str| {
            rows.iter()
                .find(|r| r.path == path)
                .unwrap_or_else(|| panic!("attribution row for {path}: {rows:?}"))
        };
        for old in ["dir/a.txt", "dir/sub/b.txt"] {
            assert_eq!(row(old).status, "deleted");
            assert_eq!(row(old).agent_id.as_deref(), Some("agent-r2"));
        }
        for new in ["moved/a.txt", "moved/sub/b.txt"] {
            assert_eq!(row(new).status, "added");
            assert_eq!(row(new).agent_id.as_deref(), Some("agent-r2"));
        }

        // The fallback commit picks up every moved path (both sides).
        let r = svc
            .git_agent_commit(
                ws,
                "agent dir rename".to_string(),
                Some(AgentId::from("agent-r2")),
                None,
                None,
                false,
                None,
            )
            .await
            .unwrap();
        for path in [
            "dir/a.txt",
            "dir/sub/b.txt",
            "moved/a.txt",
            "moved/sub/b.txt",
        ] {
            assert!(
                r.files.contains(&path.to_string()),
                "{path} committed: {:?}",
                r.files
            );
        }
        let st = intent_git::status::status(&repo.dir).unwrap();
        assert!(
            st.files.is_empty(),
            "worktree clean after the move commit: {st:?}"
        );
    }

    /// Build a bus-wired service on `repo` plus a second repo registered as a
    /// secondary git root, returning the registered root's id and path.
    async fn svc_with_registered_root(
        repo: &GitRepo,
    ) -> (TempDb, Services, WorkspaceId, GitRepo, WorkspaceGitRootId) {
        let tmp = TempDb::new();
        let store = Store::open(&tmp.path).await.expect("open store");
        let ws_id = WorkspaceId::new();
        let mut ws = workspace(&ws_id);
        ws.worktree_path = Some(repo.dir.to_string_lossy().to_string());
        store.insert_workspace(&ws).await.unwrap();
        let bus = crate::EventBus::new(store.clone());
        let svc = Services::new(store).with_event_bus(bus);
        let secondary = init_git_repo();
        let row = svc
            .git_root_register(
                ws_id.clone(),
                secondary.dir.to_string_lossy().to_string(),
                AgentId::from("agent-reg"),
            )
            .await
            .unwrap();
        let root_id = WorkspaceGitRootId(row["id"].as_str().unwrap().to_string());
        (tmp, svc, ws_id, secondary, root_id)
    }

    /// `git.agentCommit` with a `gitRootId` and explicit `files` commits in
    /// the registered secondary root (pathspec-limited, with attribution
    /// trailers), leaves the primary worktree untouched, and the emitted
    /// `git:commit` / `changes:git-status` events carry the additive
    /// `gitRootId` (with status read from the target root).
    #[tokio::test]
    async fn agent_commit_targets_registered_root_with_explicit_files() {
        let repo = init_git_repo();
        let (_t, svc, ws, secondary, root_id) = svc_with_registered_root(&repo).await;
        std::fs::write(secondary.dir.join("root.txt"), "in root\n").unwrap();
        std::fs::write(repo.dir.join("primary.txt"), "in primary\n").unwrap();

        let r = svc
            .git_agent_commit(
                ws.clone(),
                "root work".to_string(),
                Some(AgentId::from("agent-a")),
                None,
                Some(vec!["root.txt".to_string()]),
                false,
                Some(root_id.clone()),
            )
            .await
            .unwrap();
        assert_eq!(r.files, vec!["root.txt".to_string()]);
        assert_eq!(r.file_count, 1);

        // The commit landed in the secondary root, not the primary worktree,
        // and carries the attribution trailer.
        let history = intent_git::history::history(&secondary.dir, 5).unwrap();
        assert_eq!(history.len(), 2, "{history:?}");
        assert!(history[0].message.contains("root work"));
        assert_eq!(history[0].agent_id.as_deref(), Some("agent-a"));
        assert_eq!(intent_git::history::history(&repo.dir, 5).unwrap().len(), 1);
        let st = intent_git::status::status(&repo.dir).unwrap();
        let dirty: Vec<&str> = st.files.iter().map(|f| f.path.as_str()).collect();
        assert!(dirty.contains(&"primary.txt"), "{dirty:?}");

        // Both events carry the additive `gitRootId`, and the status payload
        // reflects the (now-clean) target root.
        let commits = svc
            .store()
            .events_by_type(&ws, "git:commit", 10)
            .await
            .unwrap();
        assert_eq!(commits.len(), 1);
        assert_eq!(commits[0].data["gitRootId"], root_id.as_str());
        let statuses = svc
            .store()
            .events_by_type(&ws, "changes:git-status", 10)
            .await
            .unwrap();
        assert_eq!(statuses.len(), 1);
        assert_eq!(statuses[0].data["gitRootId"], root_id.as_str());
        assert_eq!(statuses[0].data["status"]["files"], serde_json::json!([]));
    }

    /// A `userRequested` `git.agentCommit` with a `gitRootId` and no `files`
    /// commits the target root's staged index as-is (plain `git commit`
    /// semantics against the secondary root).
    #[tokio::test]
    async fn agent_commit_root_user_requested_commits_staged_index() {
        let repo = init_git_repo();
        let (_t, svc, ws, secondary, root_id) = svc_with_registered_root(&repo).await;
        std::fs::write(secondary.dir.join("staged.txt"), "staged\n").unwrap();
        std::fs::write(secondary.dir.join("unstaged.txt"), "unstaged\n").unwrap();
        let git = git2::Repository::open(&secondary.dir).unwrap();
        let mut index = git.index().unwrap();
        index.add_path(std::path::Path::new("staged.txt")).unwrap();
        index.write().unwrap();

        let r = svc
            .git_agent_commit(
                ws,
                "checkpoint".to_string(),
                None,
                None,
                None,
                true,
                Some(root_id),
            )
            .await
            .unwrap();
        assert_eq!(r.files, vec!["staged.txt".to_string()]);
        let st = intent_git::status::status(&secondary.dir).unwrap();
        let dirty: Vec<&str> = st.files.iter().map(|f| f.path.as_str()).collect();
        assert!(dirty.contains(&"unstaged.txt"), "{dirty:?}");
        assert!(!dirty.contains(&"staged.txt"), "{dirty:?}");
    }

    /// An agent-initiated (non-`userRequested`) `git.agentCommit` with a
    /// `gitRootId` but no explicit `files` is refused: the attribution
    /// pipeline only observes the primary worktree, so a secondary-root
    /// commit set cannot be attribution-filtered.
    #[tokio::test]
    async fn agent_commit_root_without_files_is_rejected() {
        let repo = init_git_repo();
        let (_t, svc, ws, secondary, root_id) = svc_with_registered_root(&repo).await;
        std::fs::write(secondary.dir.join("root.txt"), "in root\n").unwrap();

        let err = svc
            .git_agent_commit(
                ws,
                "sweep attempt".to_string(),
                Some(AgentId::from("agent-a")),
                None,
                None,
                false,
                Some(root_id),
            )
            .await
            .unwrap_err();
        assert!(
            format!("{err}").contains("requires an explicit `files` list"),
            "got: {err}"
        );
        assert_eq!(
            intent_git::history::history(&secondary.dir, 5)
                .unwrap()
                .len(),
            1
        );
    }

    /// An unknown `gitRootId` — or one registered to a different workspace —
    /// fails with the identical `Unknown git root: {id}` `InvalidParams`
    /// (`resolve_git_read_root` parity; a foreign root is indistinguishable
    /// from a nonexistent one).
    #[tokio::test]
    async fn agent_commit_rejects_unknown_and_foreign_root_ids() {
        let repo = init_git_repo();
        let (_t, svc, ws, _secondary, _root_id) = svc_with_registered_root(&repo).await;

        let unknown = WorkspaceGitRootId::new();
        let err = svc
            .git_agent_commit(
                ws.clone(),
                "msg".to_string(),
                Some(AgentId::from("agent-a")),
                None,
                Some(vec!["a.txt".to_string()]),
                false,
                Some(unknown.clone()),
            )
            .await
            .unwrap_err();
        assert!(
            matches!(err, intent_core::Error::InvalidParams(_)),
            "expected -32602, got: {err}"
        );
        assert!(
            format!("{err}").ends_with(&format!("Unknown git root: {unknown}")),
            "got: {err}"
        );

        // A root registered to ANOTHER workspace fails with the same message.
        let other_ws = WorkspaceId::new();
        svc.store()
            .insert_workspace(&workspace(&other_ws))
            .await
            .unwrap();
        let foreign_repo = init_git_repo();
        let ts = now_iso();
        let foreign = intent_core::WorkspaceGitRoot {
            id: WorkspaceGitRootId::new(),
            workspace_id: other_ws,
            path: foreign_repo.dir.to_string_lossy().into_owned(),
            source: intent_core::WorkspaceGitRootSource::Agent,
            repo_owner: None,
            repo_name: None,
            registered_by_agent_ids: vec![],
            registered_commit_sha: None,
            pr_number: None,
            pr_url: None,
            pr_status: None,
            pull_requests: None,
            created_at: ts.clone(),
            updated_at: ts,
        };
        svc.store()
            .upsert_workspace_git_root(&foreign)
            .await
            .unwrap();
        let err = svc
            .git_agent_commit(
                ws,
                "msg".to_string(),
                Some(AgentId::from("agent-a")),
                None,
                Some(vec!["a.txt".to_string()]),
                false,
                Some(foreign.id.clone()),
            )
            .await
            .unwrap_err();
        assert!(
            matches!(err, intent_core::Error::InvalidParams(_)),
            "expected -32602, got: {err}"
        );
        assert!(
            format!("{err}").ends_with(&format!("Unknown git root: {}", foreign.id)),
            "got: {err}"
        );
    }

    /// Remediation hint (monorepo#2053): a primary-target commit whose
    /// explicit `files` match nothing, where the paths exist under a
    /// registered secondary root, errors with the root's path/id and suggests
    /// passing `gitRootId`.
    #[tokio::test]
    async fn agent_commit_primary_miss_hints_at_registered_root() {
        let repo = init_git_repo();
        let (_t, svc, ws, secondary, root_id) = svc_with_registered_root(&repo).await;
        std::fs::write(secondary.dir.join("root-only.txt"), "in root\n").unwrap();

        let err = svc
            .git_agent_commit(
                ws,
                "misdirected".to_string(),
                Some(AgentId::from("agent-a")),
                None,
                Some(vec!["root-only.txt".to_string()]),
                false,
                None,
            )
            .await
            .unwrap_err();
        let msg = format!("{err}");
        assert!(msg.contains("did not match any files"), "got: {msg}");
        assert!(
            msg.contains(
                &secondary
                    .dir
                    .canonicalize()
                    .unwrap()
                    .to_string_lossy()
                    .to_string()
            ),
            "hint names the root path, got: {msg}"
        );
        assert!(msg.contains(root_id.as_str()), "hint names the id: {msg}");
        assert!(msg.contains("gitRootId"), "hint suggests gitRootId: {msg}");
    }

    /// Primary-path regression: with `git_root_id: None` an explicit-files
    /// miss that matches NO registered root keeps the bare pathspec error —
    /// no hint is appended.
    #[tokio::test]
    async fn agent_commit_primary_miss_without_matching_root_keeps_bare_error() {
        let repo = init_git_repo();
        let (_t, svc, ws, _secondary, _root_id) = svc_with_registered_root(&repo).await;

        let err = svc
            .git_agent_commit(
                ws,
                "misdirected".to_string(),
                Some(AgentId::from("agent-a")),
                None,
                Some(vec!["nowhere.txt".to_string()]),
                false,
                None,
            )
            .await
            .unwrap_err();
        let msg = format!("{err}");
        assert!(msg.contains("did not match any files"), "got: {msg}");
        assert!(!msg.contains("gitRootId"), "no hint expected: {msg}");
    }

    /// `git.commits` returns the §5.5 `{ items, nextToken }` envelope of
    /// `CommitSummary`, walking older pages via the opaque continuation
    /// token; attribution trailers populate `agentId`/`linkedNoteId`. The
    /// list payload is metadata-only — `files` is omitted (fetched on demand
    /// via `git.commitDetails`).
    #[tokio::test]
    async fn git_commits_returns_commit_summary_page() {
        let repo = init_git_repo();
        commit_file(
            &repo.dir,
            "feature.txt",
            "feature\n",
            "add feature\n\nAgent-Id: agent-7\nLinked-Note-Id: note-2\n",
        );
        let (_t, svc, ws_id) = svc_with_repo(&repo).await;

        // Page size 1 → newest commit only, with a token for the older page.
        let page1 = svc
            .git_commits(ws_id.clone(), Some(1), None, None)
            .await
            .unwrap();
        let items = page1["items"].as_array().unwrap();
        assert_eq!(items.len(), 1);
        let head = &items[0];
        assert_eq!(head["agentId"], serde_json::json!("agent-7"));
        assert_eq!(head["linkedNoteId"], serde_json::json!("note-2"));
        assert_eq!(head["author"], serde_json::json!("Test"));
        assert_eq!(head["email"], serde_json::json!("test@example.com"));
        assert!(head.get("files").is_none());
        let hash = head["hash"].as_str().unwrap();
        assert_eq!(head["sha"], serde_json::json!(hash[..7].to_string()));
        assert!(head["message"].as_str().unwrap().starts_with("add feature"));
        let token = page1["nextToken"].as_str().expect("token for older page");

        // Following the token yields the older (seed) commit, then no more.
        let page2 = svc
            .git_commits(ws_id, Some(1), Some(token.to_string()), None)
            .await
            .unwrap();
        let items2 = page2["items"].as_array().unwrap();
        assert_eq!(items2.len(), 1);
        assert!(items2[0]["message"]
            .as_str()
            .unwrap()
            .starts_with("seed commit"));
        assert_eq!(page2["nextToken"], serde_json::Value::Null);
    }

    /// `git.changes` returns the working-tree `FileStatus[]` (`path`/`status`/
    /// `staged`), including untracked files.
    #[tokio::test]
    async fn git_changes_returns_working_tree_files() {
        let repo = init_git_repo();
        std::fs::write(repo.dir.join("seed.txt"), "seed\nmore\n").unwrap();
        std::fs::write(repo.dir.join("new.txt"), "hi\n").unwrap();
        let (_t, svc, ws_id) = svc_with_repo(&repo).await;

        let changes = svc.git_changes(ws_id, None).await.unwrap();
        let arr = changes.as_array().unwrap();
        let seed = arr.iter().find(|c| c["path"] == "seed.txt").unwrap();
        assert_eq!(seed["status"], serde_json::json!("M"));
        assert_eq!(seed["staged"], serde_json::json!(false));
        let new = arr.iter().find(|c| c["path"] == "new.txt").unwrap();
        assert_eq!(new["status"], serde_json::json!("?"));
    }

    /// `git.diffs` (unstaged) returns `[{ path, hunks }]` with the FE hunk shape
    /// (`oldStart`/`oldLines`/`newStart`/`newLines`/`lines`) and `DiffLine`s
    /// tagged `Context`/`Addition`/`Deletion` with 1-based line numbers.
    #[tokio::test]
    async fn git_diffs_unstaged_returns_path_and_hunks() {
        let repo = init_git_repo();
        std::fs::write(repo.dir.join("seed.txt"), "seed\nadded\n").unwrap();
        let (_t, svc, ws_id) = svc_with_repo(&repo).await;

        let diffs = svc.git_diffs(ws_id, None, false, None, None).await.unwrap();
        let arr = diffs.as_array().unwrap();
        let f = arr.iter().find(|d| d["path"] == "seed.txt").unwrap();
        let hunks = f["hunks"].as_array().unwrap();
        assert!(!hunks.is_empty());
        let h = &hunks[0];
        assert!(h["newStart"].as_u64().is_some());
        assert!(h["oldStart"].as_u64().is_some());
        let lines = h["lines"].as_array().unwrap();
        let add = lines
            .iter()
            .find(|l| l["type"] == "Addition")
            .expect("an addition line");
        assert!(add["content"].as_str().unwrap().contains("added"));
        assert!(add["newNumber"].as_u64().is_some());
    }

    /// `git.diffs` (staged) hydrates hunks from blob SHAs and honors the `path`
    /// filter, returning only the requested file.
    #[tokio::test]
    async fn git_diffs_staged_filters_to_path() {
        let repo = init_git_repo();
        std::fs::write(repo.dir.join("seed.txt"), "seed\nstaged change\n").unwrap();
        std::fs::write(repo.dir.join("other.txt"), "other\n").unwrap();
        {
            let r = Repository::open(&repo.dir).unwrap();
            let mut idx = r.index().unwrap();
            idx.add_path(std::path::Path::new("seed.txt")).unwrap();
            idx.add_path(std::path::Path::new("other.txt")).unwrap();
            idx.write().unwrap();
        }
        let (_t, svc, ws_id) = svc_with_repo(&repo).await;

        let diffs = svc
            .git_diffs(ws_id, Some(vec!["seed.txt".to_string()]), true, None, None)
            .await
            .unwrap();
        let arr = diffs.as_array().unwrap();
        assert_eq!(arr.len(), 1);
        assert_eq!(arr[0]["path"], serde_json::json!("seed.txt"));
        assert!(!arr[0]["hunks"].as_array().unwrap().is_empty());
    }

    /// `git.diffs` (staged) on a submodule pin bump synthesizes the
    /// `Subproject commit <sha>` pseudo-hunk instead of failing to hydrate the
    /// pin SHAs as blobs (monorepo#1739).
    #[tokio::test]
    async fn git_diffs_staged_gitlink_synthesizes_subproject_hunk() {
        let repo = init_git_repo();
        let child = init_git_repo();
        add_submodule(&repo.dir, &child.dir, "sub");
        // Stage a pin bump: point the gitlink at a different (synthetic) sha.
        let new_sha = "7908777602d4e96f13c663c8a70a617163f38413";
        let old_sha = {
            let r = Repository::open(&repo.dir).unwrap();
            let mut idx = r.index().unwrap();
            let mut entry = idx.get_path(std::path::Path::new("sub"), 0).unwrap();
            let old = entry.id.to_string();
            entry.id = git2::Oid::from_str(new_sha).unwrap();
            idx.add(&entry).unwrap();
            idx.write().unwrap();
            old
        };
        let (_t, svc, ws_id) = svc_with_repo(&repo).await;

        let diffs = svc.git_diffs(ws_id, None, true, None, None).await.unwrap();
        let arr = diffs.as_array().unwrap();
        let f = arr.iter().find(|d| d["path"] == "sub").unwrap();
        let hunks = f["hunks"].as_array().unwrap();
        assert_eq!(hunks.len(), 1);
        let lines = hunks[0]["lines"].as_array().unwrap();
        assert_eq!(lines.len(), 2);
        assert_eq!(lines[0]["type"], "Deletion");
        assert_eq!(
            lines[0]["content"],
            serde_json::json!(format!("Subproject commit {old_sha}\n"))
        );
        assert_eq!(lines[1]["type"], "Addition");
        assert_eq!(
            lines[1]["content"],
            serde_json::json!(format!("Subproject commit {new_sha}\n"))
        );
    }

    /// Poll `cond` until it holds or the deadline passes (asserting on timeout).
    async fn wait_until(what: &str, mut cond: impl FnMut() -> bool) {
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while !cond() {
            assert!(
                std::time::Instant::now() < deadline,
                "timed out waiting for {what}"
            );
            tokio::time::sleep(std::time::Duration::from_millis(2)).await;
        }
    }

    /// Regression (single-flight coalescing): two concurrent identical
    /// full-tree `git.diffs` calls run the underlying walk once and both get
    /// the result. The probe parks the leader's walk on the blocking pool
    /// until the second call has provably joined as a follower, so the
    /// overlap is deterministic.
    #[tokio::test]
    async fn git_diffs_concurrent_identical_calls_coalesce_into_one_walk() {
        use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
        use std::sync::Arc;

        let repo = init_git_repo();
        std::fs::write(repo.dir.join("seed.txt"), "seed\nadded\n").unwrap();
        let (_t, svc, ws_id) = svc_with_repo(&repo).await;

        let walks = Arc::new(AtomicUsize::new(0));
        let release = Arc::new(AtomicBool::new(false));
        let svc = svc.with_git_diffs_walk_probe({
            let walks = Arc::clone(&walks);
            let release = Arc::clone(&release);
            Arc::new(move || {
                walks.fetch_add(1, Ordering::SeqCst);
                while !release.load(Ordering::SeqCst) {
                    std::thread::sleep(std::time::Duration::from_millis(2));
                }
            })
        });

        let first = tokio::spawn({
            let svc = svc.clone();
            let ws = ws_id.clone();
            async move { svc.git_diffs(ws, None, false, None, None).await }
        });
        // The leader is inside the walk (flight registered, probe parked).
        wait_until("leader to enter the walk", || {
            walks.load(Ordering::SeqCst) == 1
        })
        .await;

        let second = tokio::spawn({
            let svc = svc.clone();
            let ws = ws_id.clone();
            async move { svc.git_diffs(ws, None, false, None, None).await }
        });
        // The identical call joined the in-flight walk as a follower.
        let key = (ws_id.clone(), None, false, None, None);
        wait_until("second call to join as follower", || {
            svc.git_diffs_waiters(&key) == 1
        })
        .await;

        release.store(true, Ordering::SeqCst);
        let a = first.await.unwrap().unwrap();
        let b = second.await.unwrap().unwrap();
        assert_eq!(walks.load(Ordering::SeqCst), 1, "one underlying walk");
        assert_eq!(a, b, "both callers get the same result");
        assert!(
            a.as_array()
                .unwrap()
                .iter()
                .any(|d| d["path"] == "seed.txt"),
            "shared result carries the real diff"
        );
    }

    /// Concurrent `git.diffs` calls with different identities (here: `staged`)
    /// never coalesce — each runs its own walk.
    #[tokio::test]
    async fn git_diffs_concurrent_distinct_calls_run_their_own_walks() {
        use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
        use std::sync::Arc;

        let repo = init_git_repo();
        std::fs::write(repo.dir.join("seed.txt"), "seed\nadded\n").unwrap();
        let (_t, svc, ws_id) = svc_with_repo(&repo).await;

        let walks = Arc::new(AtomicUsize::new(0));
        let release = Arc::new(AtomicBool::new(false));
        let svc = svc.with_git_diffs_walk_probe({
            let walks = Arc::clone(&walks);
            let release = Arc::clone(&release);
            Arc::new(move || {
                walks.fetch_add(1, Ordering::SeqCst);
                while !release.load(Ordering::SeqCst) {
                    std::thread::sleep(std::time::Duration::from_millis(2));
                }
            })
        });

        let unstaged = tokio::spawn({
            let svc = svc.clone();
            let ws = ws_id.clone();
            async move { svc.git_diffs(ws, None, false, None, None).await }
        });
        wait_until("first walk", || walks.load(Ordering::SeqCst) == 1).await;
        let staged = tokio::spawn({
            let svc = svc.clone();
            let ws = ws_id.clone();
            async move { svc.git_diffs(ws, None, true, None, None).await }
        });
        // The non-identical request must start its own walk while the first
        // is still parked.
        wait_until("second independent walk", || {
            walks.load(Ordering::SeqCst) == 2
        })
        .await;

        release.store(true, Ordering::SeqCst);
        unstaged.await.unwrap().unwrap();
        staged.await.unwrap().unwrap();
        assert_eq!(walks.load(Ordering::SeqCst), 2, "no coalescing across keys");
    }

    /// Regression (monorepo#1648): concurrent `git.status` calls for one
    /// worktree run the underlying libgit2 scan once and every caller gets
    /// that result. The probe parks the leader's scan on the blocking pool
    /// until the followers have provably joined, so the overlap is
    /// deterministic.
    #[tokio::test]
    async fn git_status_concurrent_calls_coalesce_into_one_scan() {
        use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
        use std::sync::Arc;

        let repo = init_git_repo();
        std::fs::write(repo.dir.join("seed.txt"), "seed\nadded\n").unwrap();
        let (_t, svc, ws_id) = svc_with_repo(&repo).await;

        let scans = Arc::new(AtomicUsize::new(0));
        let release = Arc::new(AtomicBool::new(false));
        let svc = svc.with_git_status_scan_probe({
            let scans = Arc::clone(&scans);
            let release = Arc::clone(&release);
            Arc::new(move || {
                scans.fetch_add(1, Ordering::SeqCst);
                while !release.load(Ordering::SeqCst) {
                    std::thread::sleep(std::time::Duration::from_millis(2));
                }
            })
        });

        let leader = tokio::spawn({
            let svc = svc.clone();
            let ws = ws_id.clone();
            async move { svc.git_status(ws, None).await }
        });
        // The leader is inside the scan (flight registered, probe parked).
        wait_until("leader to enter the scan", || {
            scans.load(Ordering::SeqCst) == 1
        })
        .await;

        let followers: Vec<_> = (0..3)
            .map(|_| {
                let svc = svc.clone();
                let ws = ws_id.clone();
                tokio::spawn(async move { svc.git_status(ws, None).await })
            })
            .collect();
        wait_until("followers to join the in-flight scan", || {
            svc.git_status_waiters(&repo.dir) == 3
        })
        .await;

        release.store(true, Ordering::SeqCst);
        let first = leader.await.unwrap().unwrap();
        for follower in followers {
            assert_eq!(follower.await.unwrap().unwrap(), first, "shared result");
        }
        assert_eq!(scans.load(Ordering::SeqCst), 1, "one underlying scan");
        assert!(
            first.files.iter().any(|f| f.path == "seed.txt"),
            "shared result carries the real status"
        );
    }

    /// `accept-changes.getStatus` shares the working-tree scan with a
    /// concurrent `git.status` for the same worktree (monorepo#1648): its
    /// extra history/remote work still runs per call, but the common scan
    /// happens once.
    #[tokio::test]
    async fn accept_changes_get_status_shares_the_scan_with_git_status() {
        use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
        use std::sync::Arc;

        let repo = init_git_repo();
        std::fs::write(repo.dir.join("seed.txt"), "seed\nadded\n").unwrap();
        let (_t, svc, ws_id) = svc_with_repo(&repo).await;

        let scans = Arc::new(AtomicUsize::new(0));
        let release = Arc::new(AtomicBool::new(false));
        let svc = svc.with_git_status_scan_probe({
            let scans = Arc::clone(&scans);
            let release = Arc::clone(&release);
            Arc::new(move || {
                scans.fetch_add(1, Ordering::SeqCst);
                while !release.load(Ordering::SeqCst) {
                    std::thread::sleep(std::time::Duration::from_millis(2));
                }
            })
        });

        let status = tokio::spawn({
            let svc = svc.clone();
            let ws = ws_id.clone();
            async move { svc.git_status(ws, None).await }
        });
        wait_until("leader to enter the scan", || {
            scans.load(Ordering::SeqCst) == 1
        })
        .await;

        let accept = tokio::spawn({
            let svc = svc.clone();
            let ws = ws_id.clone();
            async move { svc.accept_changes_get_status(ws).await }
        });
        wait_until("accept-changes to join the in-flight scan", || {
            svc.git_status_waiters(&repo.dir) == 1
        })
        .await;

        release.store(true, Ordering::SeqCst);
        status.await.unwrap().unwrap();
        let value = accept.await.unwrap().unwrap();
        assert_eq!(scans.load(Ordering::SeqCst), 1, "one underlying scan");
        // Wire shape unchanged: the coalesced scan still feeds the documented
        // §5.18 counts.
        assert_eq!(value["uncommittedCount"], 1);
        assert_eq!(value["stagedCount"], 0);
    }

    /// Regression (monorepo#1693 Finding B): concurrent `accept-changes.getStatus`
    /// calls for the same workspace coalesce onto ONE full build — not just the
    /// shared working-tree scan. The scan probe parks the leader mid-scan; while
    /// parked, three more calls join and must register as followers of the
    /// *ac-status* flight (not merely as independent followers of the scan), so
    /// each of them skips the scan entirely and shares the leader's full result.
    #[tokio::test]
    async fn accept_changes_get_status_concurrent_calls_coalesce_into_one_build() {
        use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
        use std::sync::Arc;

        let repo = init_git_repo();
        std::fs::write(repo.dir.join("seed.txt"), "seed\nadded\n").unwrap();
        let (_t, svc, ws_id) = svc_with_repo(&repo).await;

        let scans = Arc::new(AtomicUsize::new(0));
        let release = Arc::new(AtomicBool::new(false));
        let svc = svc.with_git_status_scan_probe({
            let scans = Arc::clone(&scans);
            let release = Arc::clone(&release);
            Arc::new(move || {
                scans.fetch_add(1, Ordering::SeqCst);
                while !release.load(Ordering::SeqCst) {
                    std::thread::sleep(std::time::Duration::from_millis(2));
                }
            })
        });

        let leader = tokio::spawn({
            let svc = svc.clone();
            let ws = ws_id.clone();
            async move { svc.accept_changes_get_status(ws).await }
        });
        wait_until("leader to enter the scan", || {
            scans.load(Ordering::SeqCst) == 1
        })
        .await;

        let followers: Vec<_> = (0..3)
            .map(|_| {
                let svc = svc.clone();
                let ws = ws_id.clone();
                tokio::spawn(async move { svc.accept_changes_get_status(ws).await })
            })
            .collect();
        wait_until("followers to join the in-flight ac-status build", || {
            svc.ac_status_waiters(&ws_id) == 3
        })
        .await;

        release.store(true, Ordering::SeqCst);
        let first = leader.await.unwrap().unwrap();
        for follower in followers {
            assert_eq!(follower.await.unwrap().unwrap(), first, "shared result");
        }
        assert_eq!(
            scans.load(Ordering::SeqCst),
            1,
            "one underlying scan — followers never re-entered the scan"
        );
        assert_eq!(first["uncommittedCount"], 1);
    }

    /// Concurrent status scans for *different* worktrees never coalesce — they
    /// must not serialize against each other.
    #[tokio::test]
    async fn git_status_distinct_worktrees_run_their_own_scans() {
        use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
        use std::sync::Arc;

        let repo_a = init_git_repo();
        let repo_b = init_git_repo();
        let (_ta, svc, ws_a) = svc_with_repo(&repo_a).await;
        let ws_b = WorkspaceId::new();
        let mut other = workspace(&ws_b);
        other.worktree_path = Some(repo_b.dir.to_string_lossy().to_string());
        svc.store().insert_workspace(&other).await.unwrap();

        let scans = Arc::new(AtomicUsize::new(0));
        let release = Arc::new(AtomicBool::new(false));
        let svc = svc.with_git_status_scan_probe({
            let scans = Arc::clone(&scans);
            let release = Arc::clone(&release);
            Arc::new(move || {
                scans.fetch_add(1, Ordering::SeqCst);
                while !release.load(Ordering::SeqCst) {
                    std::thread::sleep(std::time::Duration::from_millis(2));
                }
            })
        });

        let first = tokio::spawn({
            let svc = svc.clone();
            async move { svc.git_status(ws_a, None).await }
        });
        wait_until("first scan", || scans.load(Ordering::SeqCst) == 1).await;
        let second = tokio::spawn({
            let svc = svc.clone();
            async move { svc.git_status(ws_b, None).await }
        });
        // The other worktree must start its own scan while the first is parked.
        wait_until("second independent scan", || {
            scans.load(Ordering::SeqCst) == 2
        })
        .await;

        release.store(true, Ordering::SeqCst);
        first.await.unwrap().unwrap();
        second.await.unwrap().unwrap();
        assert_eq!(scans.load(Ordering::SeqCst), 2, "no cross-worktree sharing");
    }

    /// A failed scan is never cached: after the flight settles, the next call
    /// runs a fresh scan.
    #[tokio::test]
    async fn git_status_failed_scan_is_not_cached() {
        use std::sync::atomic::{AtomicUsize, Ordering};
        use std::sync::Arc;

        let repo = init_git_repo();
        let (_t, svc, ws_id) = svc_with_repo(&repo).await;
        // Keep `.git` present (so the handler reaches the scan) but corrupt it
        // so `Repository::open` fails.
        std::fs::remove_file(repo.dir.join(".git").join("HEAD")).unwrap();

        let scans = Arc::new(AtomicUsize::new(0));
        let svc = svc.with_git_status_scan_probe({
            let scans = Arc::clone(&scans);
            Arc::new(move || {
                scans.fetch_add(1, Ordering::SeqCst);
            })
        });

        assert!(svc.git_status(ws_id.clone(), None).await.is_err());
        assert!(svc.git_status(ws_id, None).await.is_err());
        assert_eq!(scans.load(Ordering::SeqCst), 2, "each caller retried");
    }

