    /// Session recreate folds the outgoing session's cost into the baseline
    /// exactly like the token counters: the pre-recreate cost is neither lost
    /// nor double-counted once the fresh session reports again.
    #[tokio::test]
    async fn recreate_folds_cost_into_baseline() {
        let h = harness().await;
        let agent = AgentId::new();
        h.store
            .insert_agent_session(&agent_session(&agent, &h.ws, "opus-4.8"))
            .await
            .expect("insert session");
        h.store
            .set_acp_session_id(&h.ws, &agent, "acp-1")
            .await
            .expect("set acp id");
        let cost = |amount: f64| {
            Some(intent_core::UsageCost {
                amount,
                currency: "USD".to_string(),
            })
        };
        h.services
            .persist_turn_token_usage(&agent, &h.ws, Some(&acp_usage(100, 80, 0, 0)), cost(3.0))
            .await;
        h.store
            .replace_acp_session_id(&h.ws, &agent, "acp-1", "acp-2")
            .await
            .expect("CAS swap");

        // Recreated session, no report yet: the banked baseline cost carries.
        h.services
            .recompute_workspace_token_usage(&h.ws, false)
            .await
            .expect("recompute");
        let usage = h
            .store
            .get_workspace(&h.ws)
            .await
            .expect("reload")
            .token_usage
            .expect("usage persisted");
        assert_eq!(usage.totals.cost, cost(3.0), "baseline cost survives");

        // Fresh session reports its own cumulative cost from zero: the
        // effective total is baseline + snapshot.
        h.services
            .persist_turn_token_usage(&agent, &h.ws, Some(&acp_usage(5, 3, 0, 0)), cost(1.5))
            .await;
        let usage = h
            .store
            .get_workspace(&h.ws)
            .await
            .expect("reload 2")
            .token_usage
            .expect("usage persisted");
        assert_eq!(usage.totals.cost, cost(4.5));
        assert_eq!(usage.totals.input_tokens, 105);
    }

    /// Clobber regression (monorepo#738): the recompute persists via a scoped
    /// `token_usage` + `updated_at` write inside one transaction, so a
    /// recompute racing a workspace title update can never revert the title
    /// (the old full-row `update_workspace` replace could write back the
    /// stale title it read before the rename landed).
    #[tokio::test]
    async fn recompute_racing_title_update_does_not_revert_title() {
        let h = harness().await;
        let agent = AgentId::new();
        h.store
            .insert_agent_session(&agent_session(&agent, &h.ws, "opus-4.8"))
            .await
            .expect("insert session");

        for i in 0..10u64 {
            // A fresh snapshot each round forces the recompute to write.
            h.store
                .set_agent_session_token_usage(
                    &h.ws,
                    &agent,
                    &intent_core::TokenUsageTotals {
                        input_tokens: (i + 1) * 10,
                        output_tokens: i + 1,
                        ..Default::default()
                    },
                )
                .await
                .expect("set snapshot");
            let title = format!("Title {i}");
            let rename = {
                let store = h.store.clone();
                let ws_id = h.ws.clone();
                let title = title.clone();
                async move {
                    let mut ws = store.get_workspace(&ws_id).await.expect("get ws");
                    ws.title = title;
                    store.update_workspace(&ws).await.expect("rename");
                }
            };
            let recompute = h.services.recompute_workspace_token_usage(&h.ws, false);
            let ((), recomputed) = tokio::join!(rename, recompute);
            recomputed.expect("recompute ok");
            let ws = h.store.get_workspace(&h.ws).await.expect("reload");
            assert_eq!(ws.title, title, "recompute must never revert the title");
        }
    }

    /// Serialization (monorepo#738): N concurrent `persist_turn_token_usage`
    /// calls on one session fully serialize on the write-pool transaction —
    /// the final workspace tally equals the session's last-landed snapshot
    /// (the old read→tally→full-row-write cycle could commit a stale tally
    /// last), and every emitted `workspace:tokenUsage-changed` carries a
    /// tally equal to some committed snapshot, never a torn aggregate.
    #[tokio::test]
    async fn concurrent_persist_turn_token_usage_serializes() {
        let h = harness().await;
        let agent = AgentId::new();
        h.store
            .insert_agent_session(&agent_session(&agent, &h.ws, "opus-4.8"))
            .await
            .expect("insert session");
        let mut sub = subscribe_usage(&h);

        let snapshots: Vec<u64> = (1..=8).map(|i| i * 10).collect();
        let mut handles = Vec::new();
        for &input in &snapshots {
            let services = h.services.clone();
            let ws = h.ws.clone();
            let agent = agent.clone();
            handles.push(tokio::spawn(async move {
                services
                    .persist_turn_token_usage(
                        &agent,
                        &ws,
                        Some(&acp_usage(input, input / 10, 0, 0)),
                        None,
                    )
                    .await;
            }));
        }
        for handle in handles {
            handle.await.expect("task joined");
        }

        // The stored session snapshot is whichever cumulative report landed
        // last; the workspace tally must equal exactly that snapshot.
        let rows = h
            .store
            .get_workspace_agent_usage_data(&h.ws)
            .await
            .expect("usage rows");
        let landed = rows[0].2.as_ref().expect("snapshot landed").clone();
        assert!(
            snapshots.contains(&landed.input_tokens),
            "stored snapshot is one of the reported values"
        );
        let ws = h.store.get_workspace(&h.ws).await.expect("reload");
        let usage = ws.token_usage.expect("usage persisted");
        assert_eq!(
            usage.totals, landed,
            "workspace tally equals the last-landed session snapshot"
        );
        assert_eq!(usage.by_agent_id[&agent.0], landed);

        // Every emitted event carries a committed snapshot value — never a
        // torn/mixed aggregate.
        let mut seen = 0usize;
        while let Ok(Some(batch)) = timeout(Duration::from_millis(200), sub.recv()).await {
            for ev in batch {
                let data = serde_json::to_value(&ev).expect("serialize event");
                let input = data["data"]["tokenUsage"]["totals"]["inputTokens"]
                    .as_u64()
                    .expect("inputTokens");
                assert!(
                    snapshots.contains(&input),
                    "event tally {input} must equal a committed snapshot"
                );
                seen += 1;
            }
        }
        assert!(seen >= 1, "at least one tokenUsage-changed event fired");
    }

    /// Provider-keyed accumulation (intent-hq/intent#3794): a per-turn
    /// provider's session with a provider-prefixed compound model id, e.g.
    /// `claude-code:sonnet`.
    fn per_turn_session(agent_id: &AgentId, ws: &WorkspaceId) -> AgentSession {
        let mut session = agent_session(agent_id, ws, "claude-code:sonnet");
        session.provider = Some("claude-code".into());
        session
    }

    /// #3794: claude-agent-acp reports PER-TURN counters, so each report
    /// SUMS into the stored snapshot — persisted totals equal the sum of
    /// all turns, never just the last report (the old REPLACE undercount).
    #[tokio::test]
    async fn per_turn_provider_sums_reports_into_snapshot() {
        let h = harness().await;
        let agent = AgentId::new();
        h.store
            .insert_agent_session(&per_turn_session(&agent, &h.ws))
            .await
            .expect("insert session");

        // Turn 1 reports 70/50 (+30 cached read, +4 cached write).
        h.services
            .persist_turn_token_usage(&agent, &h.ws, Some(&acp_usage(70, 50, 30, 4)), None)
            .await;
        // Turn 2 reports 30/20 (+10, +2) — a SMALLER report than turn 1's,
        // which REPLACE would have dropped turn 1 for.
        h.services
            .persist_turn_token_usage(&agent, &h.ws, Some(&acp_usage(30, 20, 10, 2)), None)
            .await;

        let ws = h.store.get_workspace(&h.ws).await.expect("reload");
        let usage = ws.token_usage.expect("usage persisted");
        assert_eq!(usage.totals.input_tokens, 100, "sum of turns, not latest");
        assert_eq!(usage.totals.output_tokens, 70);
        assert_eq!(usage.totals.cache_read_tokens, 40);
        assert_eq!(usage.totals.cache_creation_tokens, 6);
        assert_eq!(usage.by_agent_id[&agent.0].input_tokens, 100);
    }

    /// #3795: codex-acp (and opencode/unsloth) report LAST-REQUEST counters
    /// — also summed, so totals accumulate monotonically per turn instead
    /// of bouncing to whatever the final request happened to cost.
